return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-05 23:46+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=2; plural=(n != 1);','messages' => ['WooCommerce' => 'वू कॉमर्स','Go to Plugin Search' => 'प्लगइन शोध वर जा','Activate %s' => '%s सक्रिय करा','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s ला</strong> <strong>%2$s</strong> इंस्टॉल आणि सक्रिय करणे आवश्यक आहे. <a href="%4$s">%3$s</a>','Enter your code here' => 'तुमचा कोड येथे एंटर करा.','Add %s' => '%s जोडा','Remove' => 'काढा','Order number and receipt will be sent to this email address.' => 'ऑर्डर क्रमांक आणि पावती या ईमेल पत्त्यावर पाठवली जाईल.','Apartment, unit, building, floor, etc.' => 'अपार्टमेंट, युनिट, इमारत, मजला इ.','Shipping phone' => 'पाठवण्याचा फोन','Only used for shipping-related questions.' => 'फक्त शिपिंगशी संबंधित प्रश्नांसाठी वापरले जाते.','Single step' => 'एक पाऊल','Click to go to the order summary' => 'ऑर्डर सारांशावर जाण्यासाठी क्लिक करा','Cart total:' => 'एकूण कार्ट:','Proceed to %s' => '%s वर जा','Proceed to contact' => 'संपर्क साधण्यासाठी पुढे जा','Proceed to shipping' => 'शिपिंगसाठी पुढे जा','Proceed to billing' => 'बिलिंगसाठी पुढे जा','Proceed to payment' => 'पेमेंट करण्यासाठी पुढे जा','Shipping method' => 'शिपिंग पद्धत','Additional notes' => 'अतिरिक्त नोट्स','Payment method' => 'पेमेंट पद्धत','Step %1$s of %2$s' => '%2$s पैकी %1$s पायरी','Change: %s' => 'बदल: %s','Not selected yet.' => 'अजून निवड झालेली नाही.','Same as shipping address' => 'शिपिंग पत्त्यासारखेच','Same as billing address' => 'बिलिंग पत्त्यासारखेच','Order summary' => 'ऑर्डर सारांश','Edit cart' => 'कार्ट संपादित करा','Did you mean %s?' => 'तुम्हाला %s म्हणायचे होते का?','Change email address to: {suggestion-value}' => 'ईमेल पत्ता {suggestion-value} वर बदला.','This is a required field.' => 'हे एक आवश्यक फील्ड आहे.','This is not a valid email address.' => 'हा वैध ईमेल पत्ता नाही.','This field does not match the related field value.' => 'हे फील्ड संबंधित फील्ड मूल्याशी जुळत नाही.','The CPF number "{cpf_number}" is invalid.' => '&quot;{cpf_number}&quot; हा CPF क्रमांक चुकीचा आहे.','The CNPJ number "{cnpj_number}" is invalid.' => 'CNPJ क्रमांक &quot;{cnpj_number}&quot; चुकीचा आहे.','(Required)' => '(आवश्यक)','Checkout Header - Desktop' => 'चेकआउट हेडर - डेस्कटॉप','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'मोठ्या स्क्रीनसाठी चेकआउट हेडरवर विजेट्स प्रदर्शित करा. प्लगइनचे चेकआउट हेडर वापरत असल्यासच प्रदर्शित करा.','Checkout Header - Mobile' => 'चेकआउट हेडर - मोबाइल','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'मोबाइल डिव्हाइससाठी चेकआउट हेडरच्या खाली विजेट्स प्रदर्शित करा. प्लगइनचे चेकआउट हेडर वापरत असल्यासच प्रदर्शित करा.','Checkout Sidebar' => 'चेकआउट साइडबार','Display widgets on the checkout sidebar after the order summary.' => 'ऑर्डर सारांशानंतर चेकआउट साइडबारवर विजेट्स प्रदर्शित करा.','Checkout Order Summary' => 'चेकआउट ऑर्डर सारांश','Display widgets inside the order summary at the checkout page.' => 'चेकआउट पेजवर ऑर्डर सारांशात विजेट्स प्रदर्शित करा.','Checkout Below Place Order' => 'खाली चेकआउट करा ऑर्डर द्या','Display widgets below the place order button at the checkout page.' => 'चेकआउट पेजवरील प्लेस ऑर्डर बटणाच्या खाली विजेट्स प्रदर्शित करा.','Checkout Footer' => 'चेकआउट फूटर','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'चेकआउट फूटरवर विजेट्स प्रदर्शित करा. प्लगइनचा चेकआउट फूटर वापरत असल्यासच प्रदर्शित करा.','Classic' => 'क्लासिक','Boxed' => 'बॉक्स्ड','Split' => 'स्प्लिट','Minimalist' => 'मिनिमलिस्ट','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'CodeRockz द्वारे फ्लुइड चेकआउट आणि डिलिव्हरी डेट प्लगइन्स','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>आम्हाला आढळले की तुम्ही CodeRockz द्वारे WooCommerce (मोफत आणि PRO) साठी डिलिव्हरी आणि पिकअप तारीख वेळ हे प्लगइन वापरत आहात. या प्लगइनसह एकत्रीकरण Fluid Checkout PRO मध्ये हलवण्यात आले आहे.</p>','Upgrade to PRO' => 'PRO वर अपग्रेड करा','Fluid Checkout database updated successfully' => 'फ्लुइड चेकआउट डेटाबेस यशस्वीरित्या अपडेट केला गेला.','The database changes where applied successfully.' => 'यशस्वीरित्या लागू केल्यावर डेटाबेस बदलतो.','Dismiss' => 'डिसमिस करा','Fluid Checkout database update' => 'फ्लुइड चेकआउट डेटाबेस अपडेट','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'डेटाबेसमध्ये काही बदल आवश्यक आहेत. कोणत्याही अपडेटप्रमाणे, आम्ही शिफारस करतो की तुम्ही <strong>पुढे जाण्यापूर्वी तुमच्या वेबसाइटचा संपूर्ण बॅकअप घ्या</strong> .','Update database' => 'डेटाबेस अपडेट करा','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'फ्लुइड चेकआउट हे डिव्ही बिल्डर चेकआउट लेआउटशी सुसंगत नाही.','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>फ्लुइड चेकआउटला काम करण्यासाठी क्लासिक WooCommerce शॉर्टकोड-आधारित चेकआउट फॉर्मची आवश्यकता आहे. चेकआउट पेजचा लूक आणि फील कस्टमाइझ करण्यासाठी Divi बिल्डर वापरताना, चेकआउट पेजच्या प्रत्येक भागासाठी क्लासिक शॉर्टकोड Divi बिल्डरच्या कस्टम विजेट्सने बदलले जातात. हे कस्टम विजेट्स फ्लुइड चेकआउटशी सुसंगत नाहीत.</p><p> कृपया तुमचे चेकआउट पेज Divi Builder विजेट्सऐवजी <code>[woocommerce_checkout]</code> हा शॉर्टकोड असलेला टेक्स्ट विजेट वापरून संपादित करा.</p>','Edit the checkout page' => 'चेकआउट पेज संपादित करा','Read the documentation.' => 'कागदपत्रे वाचा.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'फ्लुइड चेकआउट वापरताना जर्मनाइज्ड प्रो मल्टीस्टेप चेकआउट वैशिष्ट्य अक्षम करणे आवश्यक आहे.','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'फ्लुइड चेकआउट वापरताना, जर्मनाइज्ड प्रो प्लगइनमधील मल्टीस्टेप फीचर अनावश्यक होते आणि <strong>नवीन ऑर्डर प्रक्रिया करताना गंभीर त्रुटी</strong> निर्माण करू शकते. कृपया प्लगइन सेटिंग्जमध्ये जर्मनाइज्ड प्रो मल्टीस्टेप चेकआउट फीचर अक्षम करा.','Go to Germanized settings' => 'जर्मनाइज्ड सेटिंग्जवर जा.','Thanks for choosing Fluid Checkout!' => 'फ्लुइड चेकआउट निवडल्याबद्दल धन्यवाद!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'तुम्ही बऱ्याच काळापासून हे प्लगइन वापरत आहात. आतापर्यंत तुम्हाला ते कसे वाटले?<br> कृपया आम्हाला एक जलद रेटिंग द्या, आम्ही तुमच्या प्रत्येक अभिप्रायाचे कौतुक करतो आणि ते आम्हाला प्लगइन सुधारत राहण्यास प्रोत्साहित करते :)','Rate the plugin' => 'प्लगइनला रेट करा','I need help!' => 'मला मदत हवी आहे!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'फ्लुइड चेकआउटसह वापरताना क्वाडलेयर्सच्या WooCommerce चेकआउट मॅनेजरची काही वैशिष्ट्ये अपेक्षेनुसार काम करणार नाहीत. अधिक माहिती आणि पर्यायी उपायांसाठी <a href="%s">आमचे दस्तऐवजीकरण</a> वाचा.','Read documentation' => 'दस्तऐवजीकरण वाचा','Don\'t show this again' => 'हे पुन्हा दाखवू नका.','Fluid Checkout PRO' => 'फ्लुइड चेकआउट प्रो','More design templates' => 'अधिक डिझाइन टेम्पलेट्स','Optimized cart page' => 'ऑप्टिमाइझ केलेले कार्ट पेज','Optimized order received / thank you page' => 'ऑप्टिमाइझ केलेला ऑर्डर मिळाला / धन्यवाद पृष्ठ','Edit cart contents at checkout page' => 'चेकआउट पेजवर कार्टमधील आशय संपादित करा','Account matching / user matching' => 'खाते जुळणी / वापरकर्ता जुळणी','Trust symbols on the cart and thank you pages' => 'कार्ट आणि धन्यवाद पानांवर विश्वासाची चिन्हे','More positions for the coupon code on the checkout page' => 'चेकआउट पेजवरील कूपन कोडसाठी अधिक पोझिशन्स','International phone numbers' => 'आंतरराष्ट्रीय फोन नंबर','Gift messages and packing slips' => 'भेटवस्तू संदेश आणि पॅकिंग स्लिप','Local pickup and in-store collection' => 'स्थानिक पिकअप आणि स्टोअरमधील संग्रह','EU-VAT Assistant' => 'EU-व्हॅट सहाय्यक','I already have it – Hide this offer' => 'माझ्याकडे ते आधीच आहे - ही ऑफर लपवा.','Activated' => 'सक्रिय केले','Address book' => 'पत्ता पुस्तिका','Select an image' => 'एक प्रतिमा निवडा','Cart layout' => 'कार्ट लेआउट','Cart optimizations' => 'कार्ट ऑप्टिमायझेशन','Enable cart page optimizations' => 'कार्ट पेज ऑप्टिमायझेशन सक्षम करा','Header and footer template' => 'शीर्षलेख आणि तळटीप टेम्पलेट','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'डिस्ट्रॅक्शन फ्री पेज हेडर आणि फूटर वापरायचे की सध्या सक्रिय थीमचे हेडर आणि फूटर ठेवायचे हे नियंत्रित करते.','Distraction free header and footer' => 'विचलित न होता हेडर आणि फूटर','Theme\'s header and footer' => 'थीमचे शीर्षलेख आणि तळटीप','Cart elements' => 'कार्ट घटक','Make the order summary stay visible on the cart page while scrolling' => 'स्क्रोल करताना ऑर्डर सारांश कार्ट पेजवर दृश्यमान ठेवा.','Coupon codes' => 'कूपन कोड','Hidden' => 'लपलेले','Before the cart items section' => 'कार्ट आयटम विभागापूर्वी','Inside the cart items section' => 'कार्ट आयटम विभागाच्या आत','After the cart items section' => 'कार्ट आयटम विभागानंतर','Before the shipping section' => 'शिपिंग विभागापूर्वी','After the shipping section' => 'शिपिंग विभागानंतर','Before the order summary' => 'ऑर्डर सारांशापूर्वी','Inside the order summary' => 'ऑर्डर सारांश आत','Before the order totals' => 'ऑर्डरच्या एकूण संख्येपूर्वी','After the order totals' => 'ऑर्डरच्या एकूण संख्येनंतर','After the order summary' => 'ऑर्डर सारांशानंतर','Shipping' => 'शिपिंग','Select position where to display the shipping costs and calculator on the cart page.' => 'कार्ट पेजवर शिपिंग खर्च आणि कॅल्क्युलेटर कुठे प्रदर्शित करायचे ते स्थान निवडा.','Display as a cart section' => 'कार्ट विभाग म्हणून प्रदर्शित करा','Cross-sells' => 'क्रॉस-सेल','Select position where to display the cross-sells section on the cart page.' => 'कार्ट पेजवर क्रॉस-सेल विभाग कुठे प्रदर्शित करायचा ते स्थान निवडा.','Before the cart actions' => 'कार्ट कृती करण्यापूर्वी','After the cart actions' => 'कार्टच्या कृतींनंतर','Layout of cross-sell items on the cart page.' => 'कार्ट पेजवर क्रॉस-सेल आयटमचा लेआउट.','Optimized horizontal cross-sells layout' => 'ऑप्टिमाइझ केलेले क्षैतिज क्रॉस-सेल्स लेआउट','Theme\'s cross-sells layout' => 'थीमचा क्रॉस-सेल्स लेआउट','Number of cross-sell items to display on the cart page' => 'कार्ट पेजवर प्रदर्शित करण्यासाठी क्रॉस-सेल आयटमची संख्या','Add widget areas to the cart page' => 'कार्ट पेजवर विजेट क्षेत्रे जोडा','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'या विजेट क्षेत्रांचा वापर कार्ट पेजवर ट्रस्ट सिम्बॉल आणि ट्रस्ट बॅज जोडण्यासाठी केला जातो.','Checkout' => 'चेकआउट','Checkout layout' => 'चेकआउट लेआउट','Design template' => 'डिझाइन टेम्पलेट','Dark mode' => 'गडद मोड','Enable dark mode' => 'गडद मोड सक्षम करा','Logo image' => 'लोगो इमेज','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'चेकआउट पेज हेडरवर प्रदर्शित करण्यासाठी एक इमेज निवडा. डिस्ट्रॅक्शन फ्री हेडर आणि फूटर वापरतानाच लागू होते.','Header background color' => 'शीर्षलेख पार्श्वभूमी रंग','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'चेकआउट पेज हेडरसाठी पार्श्वभूमी रंग निवडा. फक्त डिस्ट्रॅक्शन फ्री हेडर आणि फूटर वापरताना लागू होते.','HTML color value. ie: #f3f3f3' => 'HTML रंग मूल्य. म्हणजे: #f3f3f3','Page background color' => 'पृष्ठ पार्श्वभूमी रंग','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'चेकआउट पेजसाठी पार्श्वभूमी रंग निवडा. रंग <em>बॉडी</em> एलिमेंटवर लागू केला जातो.','Footer background color' => 'फूटर पार्श्वभूमी रंग','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'चेकआउट पेज फूटरसाठी पार्श्वभूमी रंग निवडा. फक्त डिस्ट्रॅक्शन फ्री हेडर आणि फूटर वापरताना लागू होते.','Progress bar' => 'प्रगती पट्टी','Display the checkout progress bar when using multi-step checkout layout' => 'मल्टी-स्टेप चेकआउट लेआउट वापरताना चेकआउट प्रोग्रेस बार प्रदर्शित करा','Make the checkout progress bar stay visible while scrolling' => 'स्क्रोल करताना चेकआउट प्रोग्रेस बार दृश्यमान ठेवा','Express checkout' => 'एक्सप्रेस चेकआउट','Enable the express checkout section' => 'एक्सप्रेस चेकआउट विभाग सक्षम करा','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'जेव्हा समर्थित पेमेंट गेटवेमध्ये हे वैशिष्ट्य सक्षम केलेले असते तेव्हा चेकआउटच्या वेळी एक्सप्रेस चेकआउट विभाग प्रदर्शित करते.','Display express checkout buttons in one line for larger screens' => 'मोठ्या स्क्रीनसाठी एक्सप्रेस चेकआउट बटणे एकाच ओळीत प्रदर्शित करा','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'सुसंगत एक्सप्रेस चेकआउट पेमेंट गेटवे वापरून पैसे भरताना अतिरिक्त चेकआउट आवश्यक असलेल्या फील्डकडे दुर्लक्ष करा.','Make the order summary stay visible while scrolling' => 'स्क्रोल करताना ऑर्डर सारांश दृश्यमान ठेवा','Choose a background color for the order summary section.' => 'ऑर्डर सारांश विभागासाठी पार्श्वभूमी रंग निवडा.','Highlight the order totals row in the order summary table' => 'ऑर्डर सारांश सारणीमध्ये ऑर्डर बेरीज पंक्ती हायलाइट करा.','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'ऑर्डर सारांश विभागात हायलाइट केलेला पार्श्वभूमी रंग नसल्यास सर्वात उपयुक्त. फ्लुइड चेकआउट प्रो वापरताना कार्ट, ऑर्डर प्राप्त आणि ऑर्डर पहा पृष्ठांवर देखील लागू होऊ शकते.','Action link on the order summary at checkout.' => 'चेकआउट करताना ऑर्डर सारांशावरील कृती लिंक.','Edit cart link' => 'कार्ट लिंक संपादित करा','Cart items count' => 'कार्टमधील आयटमची संख्या','Link to shop page' => 'दुकानाच्या पेजची लिंक','Cart items' => 'कार्ट आयटम','Hide cart items errors at the checkout page' => 'चेकआउट पेजवर कार्ट आयटममधील त्रुटी लपवा','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'चेकआउट पेजच्या वरच्या बाजूला कार्ट आयटम एरर मेसेज दाखवू नका. खरेदी पूर्ण करण्यासाठी चेकआउट फॉर्म सबमिट करताना, हे एरर मेसेज नेहमीच दाखवले जातील.','Place order' => 'ऑर्डर द्या','Define the position to display "Place order" and terms checkbox section.' => '&quot;प्लेस ऑर्डर&quot; आणि टर्म्स चेकबॉक्स विभाग प्रदर्शित करण्यासाठी स्थान परिभाषित करा.','Some options might not be compatible with some plugins and themes.' => 'काही पर्याय काही प्लगइन्स आणि थीम्सशी सुसंगत नसतील.','Below the payment section' => 'पेमेंट विभागाच्या खाली','Below the order summary' => 'ऑर्डर सारांश खाली','Both below the payment section and the order summary' => 'पेमेंट विभागाच्या खाली आणि ऑर्डर सारांश दोन्ही','Add widget areas to the checkout page' => 'चेकआउट पेजवर विजेट क्षेत्रे जोडा','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'चेकआउट पेजवर ट्रस्ट सिम्बॉल आणि ट्रस्ट बॅज जोडण्यासाठी या विजेट क्षेत्रांचा वापर केला जातो.','Display the coupon codes section title' => 'कूपन कोड विभाग शीर्षक प्रदर्शित करा','Select position where to display the coupon codes section on the checkout page.' => 'चेकआउट पेजवर कूपन कोड विभाग कुठे प्रदर्शित करायचा ते स्थान निवडा.','Before the checkout steps' => 'चेकआउट चरणांपूर्वी','As a substep before payment methods' => 'पेमेंट पद्धतींपूर्वी एक सबस्टेप म्हणून','As a substep after payment methods' => 'पेमेंट पद्धतींनंतरचा पर्याय म्हणून','Default button style' => 'डीफॉल्ट बटण शैली','"Add" link button' => '&quot;जोडा&quot; लिंक बटण','Checkout fields' => 'चेकआउट फील्ड','Optional fields' => 'पर्यायी फील्ड','Hide optional fields behind a link button' => 'लिंक बटणामागे पर्यायी फील्ड लपवा','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'खुल्या इनपुट फील्डची संख्या कमी करण्यासाठी हा पर्याय तपासलेला ठेवण्याची शिफारस केली जाते, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">संशोधन वाचा</a> .','Do not hide "Address line 2" fields behind a link button' => 'लिंक बटणामागे &quot;अ‍ॅड्रेस लाइन २&quot; फील्ड लपवू नका.','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'जेव्हा बहुतेक ग्राहकांना &quot;अ‍ॅड्रेस लाइन २&quot; फील्डची खरोखर आवश्यकता असते किंवा जेव्हा योग्य शिपिंग पत्ता मिळवणे महत्त्वाचे असते (म्हणजे अन्न आणि इतर नाशवंत उत्पादने वितरित करताना) तेव्हाच शिफारस केली जाते.','Billing address' => 'बिलिंग पत्ता','Select position where to display the billing address section on the checkout page.' => 'चेकआउट पेजवर बिलिंग अॅड्रेस सेक्शन कुठे प्रदर्शित करायचे ते स्थान निवडा.','As a step before shipping' => 'शिपिंग करण्यापूर्वी एक पाऊल म्हणून','As a sub-step before the shipping address section' => 'शिपिंग पत्ता विभागापूर्वी एक उप-चरण म्हणून','As a sub-step after the shipping address section' => 'शिपिंग पत्ता विभागानंतर उप-चरण म्हणून','As a step after shipping' => 'शिपिंग नंतर एक पाऊल म्हणून','As a sub-step before the payment section' => 'पेमेंट विभागापूर्वी एक उप-चरण म्हणून','Force billing and shipping addresses to the same (single section)' => 'बिलिंग आणि शिपिंग पत्ते एकाच (एकच विभाग) वर सक्तीने ठेवा.','Checkbox for "Same as shipping/billing address" checked by default' => '&quot;शिपिंग/बिलिंग पत्त्यासारखेच&quot; साठी चेकबॉक्स बाय डीफॉल्ट तपासला आहे.','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'जेव्हा शिपिंग पत्ता विभाग प्रथम प्रदर्शित होईल तेव्हा &quot;शिपिंग पत्त्यासारखाच&quot; हा चेकबॉक्स डीफॉल्टनुसार चेक केल्याप्रमाणे सुरू होईल.<br> जेव्हा बिलिंग पत्ता विभाग प्रथम प्रदर्शित होईल तेव्हा &quot;बिलिंग पत्ता सारखाच&quot; हा चेकबॉक्स डीफॉल्टनुसार चेक केलेला म्हणून सुरू होईल.<br> चेकआउटच्या वेळी उघड्या इनपुट फील्डची संख्या लक्षणीयरीत्या कमी करण्यासाठी हा पर्याय तपासलेला ठेवण्याची शिफारस केली जाते, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">संशोधन वाचा</a> .','Highlight the billing address section in the checkout form' => 'चेकआउट फॉर्ममधील बिलिंग पत्ता विभाग हायलाइट करा.','Shipping address' => 'पाठवण्याचा पत्ता','Highlight the shipping address section in the checkout form' => 'चेकआउट फॉर्ममधील शिपिंग पत्ता विभाग हायलाइट करा.','Shipping methods' => 'शिपिंग पद्धती','Choose in which position to display the shipping methods section.' => 'शिपिंग पद्धती विभाग कोणत्या स्थितीत प्रदर्शित करायचा ते निवडा.','Before shipping address' => 'शिपिंग पत्त्यापूर्वी','After shipping address' => 'शिपिंग पत्ता नंतर','Local pickup' => 'स्थानिक पिकअप','Removes shipping address section when a local pickup shipping method is selected.' => 'स्थानिक पिकअप शिपिंग पद्धत निवडल्यावर शिपिंग पत्ता विभाग काढून टाकतो.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'स्थानिक पिकअप शिपिंग पद्धत निवडल्यावर शिपिंग पत्ता पिकअप पॉइंट स्थानाने बदलतो.','Choose which address to save as the shipping address for local pickup orders.' => 'स्थानिक पिकअप ऑर्डरसाठी शिपिंग पत्ता म्हणून कोणता पत्ता सेव्ह करायचा ते निवडा.','Save the selected pickup location' => 'निवडलेले पिकअप स्थान सेव्ह करा','Save same as the billing address' => 'बिलिंग पत्त्याप्रमाणेच सेव्ह करा','Do not save any shipping address' => 'कोणताही शिपिंग पत्ता सेव्ह करू नका.','Company name field for shipping address' => 'शिपिंग पत्त्यासाठी कंपनीच्या नावाचे फील्ड','Change visibility for the company name field for the shipping address section on the checkout form.' => 'चेकआउट फॉर्मवरील शिपिंग पत्ता विभागासाठी कंपनीच्या नावाच्या फील्डची दृश्यमानता बदला.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'जर फील्ड &quot;पर्यायी&quot; म्हणून सेट केले असेल, जे डीफॉल्ट दृश्यमानता स्थिती आहे, तर इतर प्लगइनना आवश्यक असलेले कोणतेही बदल लागू करण्यासाठी कोणतेही बदल लागू केले जाणार नाहीत.','Hidden (remove field)' => 'लपलेले (फील्ड काढा)','Optional' => 'पर्यायी','Required' => 'आवश्यक','Add shipping phone field to the checkout form.' => 'चेकआउट फॉर्ममध्ये शिपिंग फोन फील्ड जोडा.','Choose in which step to display the shipping phone field.' => 'शिपिंग फोन फील्ड कोणत्या चरणात प्रदर्शित करायचे ते निवडा.','Contact step' => 'संपर्क पायरी','Billing phone' => 'बिलिंग फोन','Add billing phone field to the checkout form.' => 'चेकआउट फॉर्ममध्ये बिलिंग फोन फील्ड जोडा.','Choose in which step to display the billing phone field.' => 'बिलिंग फोन फील्ड कोणत्या चरणात प्रदर्शित करायचे ते निवडा.','Show country code beside the flag' => 'ध्वजाच्या बाजूला देशाचा कोड दाखवा','Show an example of a valid phone number inside phone fields' => 'फोन फील्डमध्ये वैध फोन नंबरचे उदाहरण दाखवा.','Do not change placeholders' => 'प्लेसहोल्डर बदलू नका','Show if not defined' => 'परिभाषित नसल्यास दाखवा','Always show' => 'नेहमी दाखवा','Order notes' => 'नोट्स ऑर्डर करा','Define the visibility of the additional order notes field.' => 'अतिरिक्त ऑर्डर नोट्स फील्डची दृश्यमानता परिभाषित करा.','Gift options' => 'भेटवस्तू पर्याय','Allow customers to add a gift message and other gift related options to the order.' => 'ग्राहकांना ऑर्डरमध्ये भेटवस्तू संदेश आणि इतर भेटवस्तूंशी संबंधित पर्याय जोडण्याची परवानगी द्या.','Display the gift message as part of the order details table instead of a separate section' => 'भेटवस्तू संदेश वेगळ्या विभागाऐवजी ऑर्डर तपशील सारणीचा भाग म्हणून प्रदर्शित करा.','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'हा पर्याय ऑर्डर पुष्टीकरण पृष्ठ (धन्यवाद पृष्ठ) आणि खाते पृष्ठे, ईमेल आणि पॅकिंग स्लिपवरील ऑर्डर तपशीलांवर परिणाम करतो.','Account matching' => 'खाते जुळणी','Enable the account matching feature' => 'खाते जुळवण्याचे वैशिष्ट्य सक्षम करा','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'जेव्हा ग्राहकाच्या संपर्क तपशीलांसह खाते आधीच अस्तित्वात असेल तेव्हा अतिथी ग्राहकांच्या ऑर्डर त्यांच्या विद्यमान खात्याशी जोडा.','Display message when an account exists with the email address provided' => 'दिलेल्या ईमेल पत्त्यासह खाते अस्तित्वात असल्यास संदेश प्रदर्शित करा','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'खाते निर्मिती फील्डची जागा सूचना आणि लॉग इन करण्याच्या पर्यायाने घेते. काही संदर्भात, ग्राहकांच्या गोपनीयतेचे रक्षण करण्यासाठी हा पर्याय अक्षम ठेवण्याची शिफारस केली जाऊ शकते.','Dashboard' => 'डॅशबोर्ड','Integrations' => 'एकत्रीकरण','License keys' => 'परवाना की','Visit our website for more information about our plugins and add-ons.' => 'आमच्या प्लगइन्स आणि अ‍ॅड-ऑन्सबद्दल अधिक माहितीसाठी आमच्या वेबसाइटला भेट द्या.','Order pay page' => 'ऑर्डर पेमेंट पेज','Order pay' => 'ऑर्डर पे','Enable order pay page optimizations' => 'ऑर्डर पे पेज ऑप्टिमायझेशन सक्षम करा','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'ग्राहकाकडून प्रलंबित असलेल्या विद्यमान ऑर्डरसाठी ऑर्डर पे पे पेजचा लेआउट बदलतो.','Add widget areas to the order pay page' => 'ऑर्डर पे पेजवर विजेट क्षेत्रे जोडा.','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'ऑर्डर पे पेजवर ट्रस्ट सिम्बॉल आणि ट्रस्ट बॅज जोडण्यासाठी या विजेट क्षेत्रांचा वापर केला जातो.','Thank you page & order details layout' => 'धन्यवाद पेज आणि ऑर्डर तपशील लेआउट','Order details optimizations' => 'ऑर्डर तपशील ऑप्टिमायझेशन','Enable thank you page and order details optimizations' => 'धन्यवाद पेज आणि ऑर्डर तपशील ऑप्टिमायझेशन सक्षम करा','Changes the layout of order details on the thank you page and account pages.' => 'धन्यवाद पृष्ठ आणि खाते पृष्ठांवरील ऑर्डर तपशीलांचा लेआउट बदलतो.','Enable order details customizations on email notifications' => 'ईमेल सूचनांवर ऑर्डर तपशील कस्टमायझेशन सक्षम करा','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'ईमेल सूचनांवर नवीन विभाग प्रदर्शित करा आणि विभागांचा क्रम बदला. ईमेल सूचनांवरील ऑर्डर तपशीलांच्या शैली अपरिवर्तित राहतील.','Thank you page' => 'धन्यवाद पृष्ठ','These options affect the thank you page, also known as order received or order confirmation pages.' => 'हे पर्याय धन्यवाद पृष्ठावर परिणाम करतात, ज्याला ऑर्डर प्राप्त किंवा ऑर्डर पुष्टीकरण पृष्ठे असेही म्हणतात.','Order details layout' => 'ऑर्डर तपशील लेआउट','Display the order details with wide layout on the thank you page' => 'धन्यवाद पृष्ठावर विस्तृत लेआउटसह ऑर्डर तपशील प्रदर्शित करा.','Add widget areas to the thank you page' => 'धन्यवाद पृष्ठावर विजेट क्षेत्रे जोडा','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'या विजेट क्षेत्रांचा वापर धन्यवाद पृष्ठावर विश्वास चिन्हे आणि विश्वास बॅज जोडण्यासाठी केला जातो.','Order actions' => 'क्रिया ऑर्डर करा','Choose in which position to display the order actions.' => 'ऑर्डर क्रिया कोणत्या स्थितीत प्रदर्शित करायच्या ते निवडा.','Inside the order overview' => 'ऑर्डरच्या विहंगावलोकनाच्या आत','After the order overview' => 'ऑर्डरच्या अवलोकनानंतर','After order sections' => 'ऑर्डर विभागांनंतर','Order status' => 'ऑर्डरची स्थिती','Display the order status progress bar' => 'ऑर्डर स्थिती प्रगती पट्टी प्रदर्शित करा','Choose in which position to display the section.' => 'विभाग कोणत्या स्थितीत प्रदर्शित करायचा ते निवडा.','After the order overview and payment instructions' => 'ऑर्डरचा आढावा आणि पेमेंट सूचनांनंतर','Before the order items section' => 'ऑर्डर आयटम विभागापूर्वी','Inside the order items section' => 'ऑर्डर आयटम विभागाच्या आत','After the order items section' => 'ऑर्डर आयटम विभागानंतर','On the sidebar' => 'साइडबारवर','Order downloads' => 'डाउनलोड ऑर्डर करा','Gift message' => 'भेटवस्तू संदेश','Tools' => 'साधने','Troubleshooting' => 'समस्यानिवारण','Debug options' => 'डीबग पर्याय','Debug mode' => 'डीबग मोड','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'डीबग मोड वापरल्याने वेबसाइटच्या कामगिरीवर परिणाम होतो. फक्त समस्यानिवारण करताना हा पर्याय वापरा.','Load unminified assets' => 'अप्रमाणित मालमत्ता लोड करा','Enhanced select fields' => 'सुधारित निवड फील्ड','Fix automatic zoom-in on form fields' => 'फॉर्म फील्डमध्ये स्वयंचलित झूम-इन दुरुस्त करा','Set <code>font-size</code> inside form fields to 16px' => 'फॉर्म फील्डमधील <code>font-size</code> १६ पिक्सेल वर सेट करा.','Fluid Checkout' => 'द्रव तपासणी','Settings' => 'सेटिंग्ज','Support' => 'आधार','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => 'अधिक पर्याय अनलॉक करण्यासाठी <a target="_blank" href="%s">PRO वर अपग्रेड करा</a> .','(PRO)' => '(प्रो)','(experimental)' => '(प्रायोगिक)','Please verify your phone number.' => 'कृपया तुमचा फोन नंबर सत्यापित करा.','The Bluehost Plugin' => 'ब्लूहोस्ट प्लगइन','Custom fields' => 'कस्टम फील्ड','Enable custom shipping email field' => 'कस्टम शिपिंग ईमेल फील्ड सक्षम करा','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'सक्षम केल्यावर, ब्लूहोस्ट प्लगइनमधील शिपिंग ईमेल फील्ड चेकआउट फॉर्ममध्ये जोडला जाईल.','Captcha Pro by BestWebSoft' => 'बेस्टवेबसॉफ्ट द्वारे कॅप्चा प्रो','Captcha position' => 'कॅप्चा स्थिती','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'कॅप्चा विभाग प्रदर्शित करण्यासाठी स्थान परिभाषित करा. निवडलेल्या कॅप्चा प्रकारानुसार काही स्थाने कदाचित काम करणार नाहीत.','Selecting a pickup point is required before proceeding.' => 'पुढे जाण्यापूर्वी पिकअप पॉइंट निवडणे आवश्यक आहे.','Pickup point' => 'पिकअप पॉइंट','Pickup point not selected yet.' => 'पिकअप पॉइंट अद्याप निवडलेला नाही.','Pickup point:' => 'पिकअप पॉइंट:','Mailchimp for WooCommerce' => 'WooCommerce साठी Mailchimp','Subscribe checkbox' => 'चेकबॉक्सची सदस्यता घ्या','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'चेकआउट पेजवरील सबस्क्राइब चेकबॉक्सची स्थिती ओव्हरराइड करा आणि ती नेहमी संपर्क पायरीवर प्रदर्शित करा.','Before Shipping Address' => 'पाठवण्यापूर्वीचा पत्ता','(originally "%s")' => '(मूळतः &quot;%s&quot;)','After Shipping Address' => 'शिपिंग पत्ता नंतर','Selecting a collection point is required when shipping with FermoPoint.' => 'FermoPoint सह शिपिंग करताना कलेक्शन पॉइंट निवडणे आवश्यक आहे.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'जर चेक केले तर ते वापरकर्त्यांना ईमेलमधील चुका कळवते. (फ्लुइड चेकआउट हे वैशिष्ट्य देत असल्याने हे वैशिष्ट्य बंद करण्यात आले आहे. या पर्यायातील बदल प्रभावी होणार नाहीत)','Enable Mail Check: (disabled feature)' => 'मेल चेक सक्षम करा: (अक्षम केलेले वैशिष्ट्य)','Carrier:' => 'वाहक:','Sendinblue - WooCommerce Email Marketing' => 'सेंडिनब्लू - वूकॉमर्स ईमेल मार्केटिंग','Sign up checkbox position' => 'साइन अप चेकबॉक्सची स्थिती','Move the sign up checkbox to the contact step' => 'साइन अप चेकबॉक्स संपर्क पायरीवर हलवा','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'सक्षम केल्यावर, चेकबॉक्स सेंडिनब्लू प्लगइन सेटिंग्जमध्ये परिभाषित केलेल्या प्रदर्शन स्थानाकडे दुर्लक्ष करून संपर्क चरणावर हलविला जाईल.','Theme Betheme' => 'थीम बेथेम','Checkout progress' => 'चेकआउटची प्रगती','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'चेकआउट, कार्ट आणि ऑर्डर मिळालेल्या पेजवर बेथेममधील चेकआउट स्टेप्स सेक्शन आउटपुट करा.','Theme Fennik' => 'थीम फेनिक','Breadcrumbs' => 'ब्रेडक्रंब','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'फ्लुइड चेकआउट हेडर आणि फूटर वापरताना फेनिक थीममधून ब्रेडक्रंब्स विभाग आउटपुट करा.','Theme Go' => 'थीम गो','My account layout' => 'माझे खाते लेआउट','Enable wide layout on "My account" page.' => '&quot;माझे खाते&quot; पृष्ठावर विस्तृत लेआउट सक्षम करा.','Theme Impreza' => 'थीम इम्प्रेझा','Header' => 'शीर्षलेख','Spacing for site header at the checkout page (in pixels)' => 'चेकआउट पेजवर साइट हेडरसाठी अंतर (पिक्सेलमध्ये)','Only applicable when using the Impreza theme header at the checkout page.' => 'चेकआउट पेजवर इम्प्रेझा थीम हेडर वापरतानाच लागू.','Theme Kapee' => 'थीम कापी','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'चेकआउट, कार्ट आणि ऑर्डर मिळालेल्या पृष्ठांवर कापी थीममधील चेकआउट स्टेप्स विभाग आउटपुट करा.','Theme Porto' => 'थीम पोर्टो','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'चेकआउट, कार्ट आणि ऑर्डर मिळालेल्या पृष्ठांवर पोर्टो थीममधील चेकआउट स्टेप्स विभाग आउटपुट करा.','Theme Pressmart' => 'थीम प्रेसमार्ट','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'चेकआउट, कार्ट आणि ऑर्डर मिळालेल्या पृष्ठांवर प्रेसमार्ट थीममधील चेकआउट स्टेप्स विभाग आउटपुट करा.','Theme The Gem' => 'थीम द जेम','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'फ्लुइड चेकआउट हेडर आणि फूटर वापरताना द जेम थीममधून चेकआउट स्टेप्स सेक्शन आउटपुट करा.','Theme Woodmart' => 'थीम वुडमार्ट','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'फ्लुइड चेकआउट हेडर आणि फूटर वापरताना वुडमार्ट थीममधून चेकआउट स्टेप्स सेक्शन आउटपुट करा.','Checkout options' => 'चेकआउट पर्याय','Disable the theme checkout options' => 'थीम चेकआउट पर्याय अक्षम करा','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'थीमद्वारे जोडलेल्या उत्पादनाची प्रतिमा, प्रमाण फील्ड, काढून टाका बटण आणि उत्पादन पृष्ठाची लिंक प्रदर्शित करणे हे पर्याय डीफॉल्टनुसार अक्षम केले जातात.','Theme Atomion' => 'थीम अॅटोमियन','Order progress' => 'ऑर्डर प्रगती','Display order progress from the theme' => 'थीमवरून ऑर्डर प्रगती प्रदर्शित करा','Display the form field labels visible on the page' => 'पृष्ठावर दृश्यमान फॉर्म फील्ड लेबल्स प्रदर्शित करा.','It is recommended to keep this option enabled for a better user experience.' => 'चांगल्या वापरकर्त्याच्या अनुभवासाठी हा पर्याय सक्षम ठेवण्याची शिफारस केली जाते.','Theme ZK Nito' => 'थीम झेडके नितो','Add extra fields to the checkout form' => 'चेकआउट फॉर्ममध्ये अतिरिक्त फील्ड जोडा.','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'शिपिंग पत्ता विभागात अतिरिक्त शिपिंग ईमेल आणि शिपिंग फोन फील्ड जोडते.','Go to the home page' => 'मुख्यपृष्ठावर जा.','Skip to content' => 'सामग्रीवर जा','Create an account' => 'खाते तयार करा','Log in to your account' => 'तुमच्या खात्यात लॉग इन करा.','Already have an account?' => 'आधीपासूनच खाते आहे?','Logged in as %1$s. <a href="%2$s">Log out</a>' => '%1$s म्हणून लॉग इन केले. <a href="%2$s">लॉग आउट करा.</a>','Your order has a total amount due of %s. No further payment is needed.' => 'तुमच्या ऑर्डरची एकूण देय रक्कम %s आहे. आणखी कोणतेही पेमेंट आवश्यक नाही.','Close and continue with checkout' => 'बंद करा आणि चेकआउट सुरू ठेवा','Continue' => 'सुरू ठेवा','Parcel terminal' => 'पार्सल टर्मिनल','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>हे विजेट फ्लुइड चेकआउटने बदलले आहे.</p><p> फ्लुइड चेकआउट वापरताना, चेकआउट पेज योग्यरित्या कार्य करण्यासाठी मूळ WooCommerce शॉर्टकोड <code>[woocommerce_checkout]</code> वापरणे आवश्यक आहे.</p><p> अधिक माहितीसाठी, फ्लुइड चेकआउट दस्तऐवजीकरणाला भेट द्या.</p>','Theme The7' => 'थीम द७','Additional header sections' => 'अतिरिक्त शीर्षलेख विभाग','Output additional header sections if enabled in the theme settings.' => 'थीम सेटिंग्जमध्ये सक्षम केले असल्यास अतिरिक्त शीर्षलेख विभाग आउटपुट करा.','More information' => 'अधिक माहिती','Pick a Locker' => 'लॉकर निवडा','Page template' => 'पेज टेम्पलेट','Use `Order confirmation` page template for block-based themes' => 'ब्लॉक-आधारित थीमसाठी `ऑर्डर कन्फर्मेशन` पेज टेम्पलेट वापरा.','Only applies when using a block-based theme.' => 'ब्लॉक-आधारित थीम वापरतानाच लागू होते.','WooCommerce Stripe Gateway' => 'वू कॉमर्स स्ट्राइप गेटवे','Payment form' => 'पेमेंट फॉर्म','Apply styles to the Stripe payment form fields' => 'स्ट्राइप पेमेंट फॉर्म फील्डमध्ये शैली लागू करा.','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'सक्षम केल्यावर, फ्लुइड चेकआउट प्लगइनसह सुसंगततेसाठी ऑप्टिमाइझ केलेल्या शैली लागू करेल. जर तुम्ही स्ट्राइप पेमेंट फॉर्म फील्डसाठी कस्टम शैली वापरत असाल तर तुम्ही हे अक्षम करू शकता.','Theme Nyture' => 'थीम न्युचर','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'फ्लुइड चेकआउट वापरताना Nyture थीममधून चेकआउट स्टेप्स सेक्शन आउटपुट करा.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'ग्राहकांना स्टोअर अ‍ॅडमिनने मॅन्युअली तयार केलेल्या किंवा चेकआउट दरम्यान पूर्ण न झालेल्या ऑर्डरसाठी पैसे देण्याची परवानगी देते.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'क्वाडलेयर्सचे वूकॉमर्स चेकआउट मॅनेजर प्लगइन फ्लुइड चेकआउटशी सुसंगत नाही.','Company name field for billing address' => 'बिलिंग पत्त्यासाठी कंपनीचे नाव फील्ड','Change visibility for the company name field for the billing address section on the checkout form.' => 'चेकआउट फॉर्मवरील बिलिंग पत्ता विभागासाठी कंपनीच्या नावाच्या फील्डची दृश्यमानता बदला.','Theme Bookshelf' => 'थीम बुकशेल्फ','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'फ्लुइड चेकआउट वापरताना बुकशेल्फ थीममधून चेकआउट स्टेप्स सेक्शन आउटपुट करा.','Account password' => 'खात्याचा पासवर्ड','An account will be created with the information provided at checkout when completing the order.' => 'ऑर्डर पूर्ण करताना चेकआउट करताना दिलेल्या माहितीसह एक खाते तयार केले जाईल.','Choose the style of the progress bar.' => 'प्रोग्रेस बारची शैली निवडा.','Bars' => 'बार','Theme Ireca' => 'थीम इरेका','WooCommerce page layout' => 'WooCommerce पेज लेआउट','Force wide layout on WooCommerce pages' => 'WooCommerce पेजवर विस्तृत लेआउटची सक्ती करा','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'हे सुनिश्चित करते की चेकआउट, कार्ट, ऑर्डर प्राप्त, ऑर्डर पे आणि खाते पृष्ठांसह WooCommerce पृष्ठांवर सामग्री विभाग खूप अरुंद नाही.','WooCommerce Smart Coupons' => 'वू कॉमर्स स्मार्ट कूपन','Position on checkout page' => 'चेकआउट पेजवरील स्थिती','Choose where to display the available coupons section on the checkout page.' => 'चेकआउट पेजवर उपलब्ध कूपन विभाग कुठे प्रदर्शित करायचा ते निवडा.','Before the progress bar' => 'प्रगती पट्टीच्या आधी','After the progress bar' => 'प्रगती पट्टी नंतर','Before coupon codes section' => 'कूपन कोड विभागापूर्वी','Format phone numbers according to the rules for each country.' => 'प्रत्येक देशाच्या नियमांनुसार फोन नंबर फॉरमॅट करा.','Use precise phone number validation' => 'अचूक फोन नंबर पडताळणी वापरा','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'हे एक प्रायोगिक वैशिष्ट्य आहे आणि सर्व सेटअपमध्ये अपेक्षेप्रमाणे काम करू शकत नाही. ते सावधगिरीने वापरा.','Phone number validation types used when precise validation is enabled.' => 'अचूक प्रमाणीकरण सक्षम केलेले असताना वापरले जाणारे फोन नंबर प्रमाणीकरण प्रकार.','Mobile' => 'मोबाईल','Fixed line' => 'स्थिर रेषा','Toll free' => 'टोल फ्री','Or' => 'किंवा','Contact' => 'संपर्क करा','Multi step' => 'मल्टी स्टेप','2 columns' => '२ स्तंभ','1 column' => '१ स्तंभ','Before checkout steps' => 'चेकआउट करण्यापूर्वीच्या पायऱ्या','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => '<em>&quot;१ कॉलम&quot;</em> चेकआउट लेआउट वापरताना हा पर्याय नेहमी <em>&quot;चेकआउट चरणांपूर्वी&quot;</em> वर सेट केला जातो आणि डेस्कटॉप व्ह्यूला देखील लागू होतो.','Position for the extra order summary section on mobile.' => 'मोबाईलवरील अतिरिक्त ऑर्डर सारांश विभागासाठी स्थान.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => '<em>&quot;साइटवरील शीर्षलेख&quot;</em> हा पर्याय फक्त विचलित-मुक्त शीर्षलेख वापरताना लागू होतो.','On the site header (requires distraction-free header)' => 'साइट हेडरवर (विचलित न करता येणारे हेडर आवश्यक आहे)','Initial state for the expansible order summary section on mobile.' => 'मोबाईलवरील विस्तारित ऑर्डर सारांश विभागाची प्रारंभिक स्थिती.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'नियामक आवश्यकतांनुसार आम्ही खालील देशांसाठी ते <em>विस्तारित</em> म्हणून सेट करण्याची शिफारस करतो: <strong>जर्मनी</strong> , <strong>ऑस्ट्रिया</strong> , <strong>स्वित्झर्लंड</strong> , <strong>नेदरलँड्स</strong> , <strong>पोलंड</strong> , <strong>बेल्जियम</strong> आणि <strong>फ्रान्स</strong> .','Collapsed' => 'कोलॅप्स झाले','Expanded' => 'विस्तारित','Do not show' => 'दाखवू नका','yes' => 'होय','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'जर बिलिंग पत्त्याचा विभाग शिपिंग पत्त्याच्या विभागानंतर दिसत असेल आणि बिलिंग फोन फील्ड &#39;आवश्यक&#39; म्हणून सेट केले असेल, तर शिपिंग फोन फील्ड &#39;आवश्यक&#39; म्हणून सक्तीने सेट केले जाऊ शकते. हे सुनिश्चित करण्यासाठी आवश्यक आहे की, जेव्हा तो पर्याय निवडला जातो, तेव्हा शिपिंग पत्ता बिलिंग पत्त्यावर कॉपी केला जाऊ शकेल, अन्यथा ग्राहक चेकआउट फॉर्म पूर्ण करू शकणार नाही.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'जर बिलिंग पत्त्याचा विभाग शिपिंग पत्त्याच्या विभागाच्या आधी दिसत असेल आणि शिपिंग फोन फील्ड &#39;आवश्यक&#39; म्हणून सेट केले असेल, तर बिलिंग फोन फील्ड &#39;आवश्यक&#39; म्हणून सक्तीने सेट केले जाऊ शकते. हे आवश्यक आहे जेणेकरून जेव्हा तो पर्याय निवडला जातो, तेव्हा शिपिंग पत्ता बिलिंग पत्त्यावर कॉपी केला जाऊ शकेल, अन्यथा ग्राहक चेकआउट फॉर्म पूर्ण करू शकणार नाही.','Settings profiles' => 'सेटिंग्ज प्रोफाइल','Settings profile' => 'सेटिंग्ज प्रोफाइल','You do not have permission to perform this action.' => 'तुम्हाला ही कृती करण्याची परवानगी नाही.','You do not have permission to activate plugins.' => 'तुम्हाला प्लगइन सक्रिय करण्याची परवानगी नाही.','Missing plugin.' => 'प्लगइन उपलब्ध नाही.','Plugin activated.' => 'प्लगिन सक्रिय झाले आहे.','The following changes will be applied:' => 'खालील बदल लागू केले जातील:','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'फ्लूइड चेकआउट ५.० पासून, सेटिंग्ज वेगळ्या पद्धतीने सेव्ह केल्या जातात. गरज पडल्यास मागील आवृत्त्यांवर डाउनग्रेड करता यावे यासाठी, जुने पर्याय अजूनही डेटाबेसमध्ये साठवलेले आहेत.','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'तुमचे स्टोअर नवीन सेटिंग्जवर सुमारे २ आठवड्यांपासून चालू आहे, त्यामुळे तुम्ही डेटाबेसमध्ये संग्रहित असलेले जुने पर्याय काढून टाकू शकता. कृपया लक्षात घ्या की साफसफाईनंतर, जर तुम्हाला प्लगइनच्या मागील आवृत्त्यांवर परत जाण्याची आवश्यकता भासल्यास, ते सर्व सेटिंग्जसाठी डीफॉल्ट मूल्ये वापरेल.','Fluid Checkout settings cleanup' => 'फ्लुइड चेकआउट सेटिंग्ज क्लीनअप','Delete leftover options' => 'उरलेले पर्याय हटवा','Help us improve Fluid Checkout' => 'फ्लुइड चेकआउट सुधारण्यासाठी आम्हाला मदत करा.','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'जलद सहाय्य मिळवण्यासाठी आणि सुसंगतता सुधारण्यास व परिणामांचे मोजमाप करण्यास आम्हाला मदत करण्यासाठी, अनामिक साइट पर्यावरण अहवाल फ्लूइड चेकआउटसोबत शेअर करा. यामध्ये कोणताही ग्राहक, वापरकर्ता किंवा संवेदनशील डेटा समाविष्ट नसतो. टूल्स सेटिंग्जमधून काय शेअर करायचे आहे, हे तुम्ही कधीही निवडू शकता.','Enable site environment reports' => 'साइट पर्यावरण अहवाल सक्षम करा','Review settings' => 'सेटिंग्जचे पुनरावलोकन करा','This preview has expired. Reload the admin page to start a new preview.' => 'या प्रिव्ह्यूची मुदत संपली आहे. नवीन प्रिव्ह्यू सुरू करण्यासाठी ॲडमिन पेज रीलोड करा.','Preview expired' => 'पूर्वावलोकन कालबाह्य झाले.','Orders cannot be placed in the preview.' => 'प्रिव्ह्यूमध्ये ऑर्डर देता येत नाहीत.','Logging in is not available in the preview.' => 'प्रिव्ह्यूमध्ये लॉग इन करण्याची सुविधा उपलब्ध नाही.','Accounts cannot be created in the preview.' => 'प्रिव्ह्यूमध्ये खाती तयार करता येत नाहीत.','Requests to other sites are blocked in the preview.' => 'प्रिव्ह्यूमध्ये इतर साइट्सवरील विनंत्या अवरोधित केल्या आहेत.','Processing…' => 'प्रक्रिया सुरू आहे…','Something went wrong. Please try again.' => 'काहीतरी चूक झाली आहे. कृपया पुन्हा प्रयत्न करा.','Activate plugin' => 'प्लगइन सक्रिय करा','Fluid Checkout PRO - The complete checkout package' => 'फ्लुइड चेकआउट प्रो - संपूर्ण चेकआउट पॅकेज','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'सर्व प्रो वैशिष्ट्ये + सर्व अॅड-ऑन्स, एकाच किंमतीत. डिझाइन टेम्पलेट्स, ऑप्टिमाइझ केलेले कार्ट आणि ऑर्डर मिळाल्याची पृष्ठे, खाते जुळवणी, आणि बरेच काही.','Optimized order pay page' => 'ऑप्टिमाइझ केलेले ऑर्डर पेमेंट पेज','Express checkout buttons from supported payment methods' => 'समर्थित पेमेंट पद्धतींमधील एक्सप्रेस चेकआउट बटणे','Delayed account creation' => 'खाते तयार करण्यास विलंब','Address autocomplete with Google Maps APIs' => 'गुगल मॅप्स एपीआय वापरून पत्ता आपोआप पूर्ण करणे','Multiple saved addresses with the address book' => 'अॅड्रेस बुकसह अनेक सेव्ह केलेले पत्ते','EU-VAT assistant' => 'ईयू-व्हॅट सहाय्यक','Hide this section' => 'हा विभाग लपवा','Learn more' => 'अधिक जाणून घ्या','Get early access' => 'लवकर प्रवेश मिळवा','Activate add-on' => 'अ‍ॅड-ऑन सक्रिय करा','Get more out of your checkout journey' => 'तुमच्या खरेदी प्रक्रियेचा अधिक फायदा घ्या','Test API key' => 'चाचणी API की','Guided setup' => 'मार्गदर्शित सेटअप','Options' => 'पर्याय','Set up layout and design on the <a href="%s">checkout options</a>.' => '<a href="%s">चेकआउट पर्यायांवर</a> लेआउट आणि डिझाइन सेट करा.','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'अतिथी चेकआउट सक्षम करा आणि/किंवा <a href="%s">ग्राहक खाते सेटिंग्जचे</a> पुनरावलोकन करा.','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'ऑप्टिमाइझ केलेले <a href="%1$s">कार्ट</a> , <a href="%2$s">थँक्यू</a> आणि <a href="%3$s">ऑर्डर पे</a> पेजेस सक्षम करा.','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'गुगल मॅप्सवरून <a href="%s">पत्ता ऑटो-कंप्लीट करण्याची</a> सुविधा चालू करा.','Enable multiple saved addresses with <a href="%s">address book</a>.' => '<a href="%s">अॅड्रेस बुकच्या</a> मदतीने एकापेक्षा जास्त पत्ते सेव्ह करण्याची सुविधा द्या.','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'तुम्ही इन्स्टॉल केलेल्या थीम किंवा इतर प्लगइन्ससाठी कोणतेही <a href="%s">इंटिग्रेशन पर्याय</a> उपलब्ध आहेत का ते तपासा.','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'जलद साहाय्य मिळवा आणि सुसंगतता सुधारण्यास व परिणामांचे मोजमाप करण्यास आम्हाला मदत करा. टूलच्या सेटिंग्जमधून <a href="%s">वापराचा मागोवा घेणे सक्षम करा</a> .','Missing settings tab.' => 'सेटिंग्ज टॅब उपलब्ध नाही.','Getting started' => 'सुरुवात करणे','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>उत्तम! तुमचे चेकआउट पेज आता फ्लुइड चेकआउटवर सुरू झाले आहे.</strong> सुरुवात करण्यासाठी पुढीलप्रमाणे काही पायऱ्या आहेत:','Completed' => 'पूर्ण झाले','Preview report data' => 'पूर्वावलोकन अहवाल डेटा','Send now' => 'आता पाठवा','Auto-detect' => 'स्वयंचलितपणे शोधा','Afrikaans' => 'आफ्रिकन','Albanian' => 'अल्बेनियन','Amharic' => 'अम्हारिक','Arabic' => 'अरबी','Armenian' => 'आर्मेनियन','Azerbaijani' => 'अझरबैजानी','Basque' => 'बास्क','Belarusian' => 'बेलारूसी','Bengali' => 'बंगाली','Bosnian' => 'बोस्नियन','Bulgarian' => 'बल्गेरियन','Burmese' => 'बर्मीज','Catalan' => 'कॅटलान','Chinese' => 'चीनी','Chinese (Simplified)' => 'चीनी (सरलीकृत)','Chinese (Hong Kong)' => 'चीनी (हाँगकाँग)','Chinese (Traditional)' => 'चीनी (पारंपरिक)','Croatian' => 'क्रोएशियन','Czech' => 'चेक','Danish' => 'डॅनिश','Dutch' => 'डच','English' => 'इंग्रजी','English (Australian)' => 'इंग्रजी (ऑस्ट्रेलियन)','English (Great Britain)' => 'इंग्रजी (ग्रेट ब्रिटन)','Estonian' => 'एस्टोनियन','Farsi' => 'फारसी','Finnish' => 'फिनिश','Filipino' => 'फिलिपिनो','French' => 'फ्रेंच','French (Canadian)' => 'फ्रेंच (कॅनेडियन)','Galician' => 'गॅलिशियन','Georgian' => 'जॉर्जियन','German' => 'जर्मन','Greek' => 'ग्रीक','Gujarati' => 'गुजराती','Hebrew' => 'हिब्रू','Hindi' => 'हिंदी','Hungarian' => 'हंगेरियन','Icelandic' => 'आईसलँडिक','Indonesian' => 'इंडोनेशियन','Italian' => 'इटालियन','Japanese' => 'जपानी','Kannada' => 'कन्नड','Kazakh' => 'कझाक','Khmer' => 'ख्मेर','Korean' => 'कोरियन','Kyrgyz' => 'किर्गिझ','Lao' => 'लाओ','Latvian' => 'लॅटव्हियन','Lithuanian' => 'लिथुआनियन','Macedonian' => 'मॅसेडोनियन','Malay' => 'मलय','Malayalam' => 'मल्याळम','Marathi' => 'मराठी','Mongolian' => 'मंगोलियन','Nepali' => 'नेपाळी','Norwegian' => 'नॉर्वेजियन','Polish' => 'पोलिश','Portuguese' => 'पोर्तुगीज','Portuguese (Brazil)' => 'पोर्तुगीज (ब्राझील)','Portuguese (Portugal)' => 'पोर्तुगीज (पोर्तुगाल)','Punjabi' => 'पंजाबी','Romanian' => 'रोमानियन','Russian' => 'रशियन','Serbian' => 'सर्बियन','Sinhalese' => 'सिंहली','Slovak' => 'स्लोव्हाक','Slovenian' => 'स्लोव्हेनियन','Spanish' => 'स्पॅनिश','Spanish (Latin America)' => 'स्पॅनिश (लॅटिन अमेरिका)','Swahili' => 'स्वाहिली','Swedish' => 'स्वीडिश','Tamil' => 'तमिळ','Telugu' => 'तेलगू','Thai' => 'थाई','Turkish' => 'तुर्की','Ukrainian' => 'युक्रेनियन','Urdu' => 'उर्दू','Vietnamese' => 'व्हिएतनामी','Zulu' => 'झुलू','Google address autocomplete' => 'गुगल पत्ता ऑटो-कंप्लीट','Google Places API version' => 'गुगल प्लेसेस एपीआय आवृत्ती','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'Google Places API ची कोणती आवृत्ती वापरायची ते निवडा. आम्ही शक्य तितक्या लवकर नवीन Places API वर स्थलांतरित होण्याची शिफारस करतो.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'आम्ही &quot;प्लेसेस एपीआय (नवीन)&quot; वापरण्याची शिफारस करतो, कारण १ मार्च २०२५ पासून, गूगल &quot;प्लेसेस एपीआय (लेगसी)&quot; आवृत्तीला लेगसी स्थितीत हलवेल. याचा अर्थ असा की, तुम्ही नवीन एपीआय की साठी ही सेवा यापुढे सक्षम करू शकणार नाही आणि एपीआयची ती आवृत्ती अखेरीस उपलब्ध राहणार नाही. लेगसी एपीआय आधीपासून वापरत असलेली विद्यमान खाती कोणत्याही व्यत्ययाशिवाय काम करत राहू शकतात.','(Recommended)' => '(शिफारस केलेले)','Google API key' => 'गुगल एपीआय की','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'तुमची गूगल एपीआय की पेस्ट करा आणि ती या वेबसाइटसाठी काम करते की नाही हे तपासण्यासाठी टेस्ट बटण वापरा. की वैध आहे आणि तुमच्या डोमेनसाठी अनुमत आहे याची खात्री करा, अन्यथा ॲड्रेस फील्ड ब्लॉक होऊ शकते, ज्यामुळे ग्राहकांना त्यांच्या ऑर्डर पूर्ण करता येणार नाहीत.','Enable Google address autocomplete' => 'गुगल पत्ता ऑटो-कंप्लीट सक्षम करा','Enable address autocompletion using the Google Maps APIs.' => 'गुगल मॅप्स एपीआय वापरून पत्ता स्वयंचलितपणे पूर्ण करण्याची सुविधा सक्षम करा.','Google API language' => 'गुगल एपीआय भाषा','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'गुगल प्लेसेस एपीआयच्या पत्त्यांच्या सूचना दाखवण्यासाठी या भाषेचा वापर केला जाईल आणि पत्तेदेखील याच भाषेत आपोआप पूर्ण केले जातील.','Result types' => 'निकालाचे प्रकार','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'कोणत्याही प्रकारचे निकाल स्वीकारण्यासाठी रिकामे सोडा, ज्यामुळे सहसा अधिक चांगले जुळणारे निकाल मिळतात. <a href="%s" target="_blank">अधिक तपशिलांसाठी दस्तऐवज पहा</a> .<br> अॅड्रेस ऑटो-कंप्लीट फील्डवर मिळवण्यासाठी, पत्ता शोध परिणामांच्या ५ प्रकारांपर्यंत निवडा.<br> <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">समर्थित प्रकारांबद्दल</a> अधिक जाणून घेण्यासाठी गूगल मॅप्सच्या दस्तऐवजांना भेट द्या.','Result types (Legacy API)' => 'निकालाचे प्रकार (लेगसी एपीआय)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'प्लेसेस एपीआय (लेगसी) वापरताना कोणत्या प्रकारचे पत्ता शोध परिणाम परत करायचे.<br> <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">समर्थित प्रकारांबद्दल</a> अधिक जाणून घेण्यासाठी लेगसी गूगल प्लेसेस एपीआयच्या डॉक्युमेंटेशनला भेट द्या.','Company fields' => 'कंपनीची क्षेत्रे','Enable autocomplete for the company name if available' => 'कंपनीचे नाव उपलब्ध असल्यास, त्यासाठी ऑटो-कंप्लीट चालू करा.','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'गुगल मॅप्स एपीआयकडून कंपनीच्या नावाची माहिती मिळाल्यावर, कंपनी फील्डमध्ये ती माहिती आपोआप भरण्याची (ऑटो-कंप्लीशन) सुविधा सक्षम करा.','Business search' => 'व्यवसाय शोध','Enable search for businesses in the company field' => 'कंपनी फील्डमध्ये व्यवसायांचा शोध सक्षम करा','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'कंपनी फील्डमध्ये टाईप करताना व्यवसायाशी संबंधित पत्त्यांच्या सूचना सक्षम करा, त्यानंतर सूचनांमधून व्यवसाय निवडल्यावर पत्त्यांची सर्व फील्ड्स आपोआप पूर्ण करा.','Company result types' => 'कंपनी निकालाचे प्रकार','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'ऑटो-कंप्लीट कंपनी फील्डवर मिळवण्यासाठी पत्त्याच्या शोध परिणामांच्या ५ प्रकारांपर्यंत निवडा.<br> शिफारस केलेले मूल्य <code>establishment</code> आहे, ज्यामध्ये बहुतेक प्रकारच्या व्यवसायांचा समावेश होतो.<br> व्यवसायांशी संबंधित नसलेल्या निकालांसह, कोणत्याही प्रकारचे निकाल स्वीकारण्यासाठी हे रिकामे सोडा.<br> <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">समर्थित प्रकारांबद्दल</a> अधिक जाणून घेण्यासाठी गूगल मॅप्सच्या दस्तऐवजांना भेट द्या.','Google logo' => 'गुगल लोगो','Show text and logo "Powered by Google"' => '&quot;Powered by Google&quot; हा मजकूर आणि लोगो दाखवा','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'निवडल्यावर, पत्त्याच्या ऑटो-कंप्लीट सूचना बॉक्सच्या तळाशी &quot;Powered by Google&quot; हा मजकूर आणि लोगो प्रदर्शित केला जाईल.','Brasil API address autocomplete' => 'ब्राझील API पत्ता ऑटो-कंप्लीट','Brasil API' => 'ब्राझील एपीआय','Enable Brasil API address autocomplete for CEP fields' => 'CEP फील्डसाठी ब्राझील API पत्ता ऑटो-कंप्लीट सक्षम करा','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'CEP/पोस्टकोड फील्ड वापरून पत्ते मिळवण्यासाठी आणि आपोआप भरण्यासाठी ब्राझील API वापरा. केवळ ब्राझीलमधील पत्त्यांसाठी लागू.','API version' => 'API आवृत्ती','Choose which version of the Brasil API CEP method to use.' => 'ब्राझील API CEP पद्धतीची कोणती आवृत्ती वापरायची ते निवडा.','Address book migration' => 'पत्ता पुस्तक स्थलांतर','WooCommerce addresses' => 'वू कॉमर्स पत्ते','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'WooCommerce मधील विद्यमान शिपिंग आणि बिलिंग पत्ते ग्राहकांच्या अॅड्रेस बुकमध्ये कॉपी करा.','Enable the address book feature' => 'अॅड्रेस बुक फीचर सक्षम करा','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'ग्राहकांना एकापेक्षा जास्त पत्ते जतन करण्याची आणि शिपिंग व बिलिंगसाठी वापरला जाणारा डीफॉल्ट पत्ता निश्चित करण्याची परवानगी द्या.','Address labels' => 'पत्त्याचे लेबल','Allow customers to add a custom label for each address' => 'ग्राहकांना प्रत्येक पत्त्यासाठी स्वतःचे लेबल लावण्याची परवानगी द्या.','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'पत्त्याच्या लेबल्समुळे ग्राहकांना त्यांचे जतन केलेले पत्ते (उदा.: &quot;आईचे घर&quot;) ओळखणे सोपे जाते. ही पत्त्याची लेबल्स ग्राहकांसाठी खाजगी असतात आणि ती ऑर्डर तपशील पृष्ठावर किंवा पावत्यांवर प्रदर्शित किंवा छापली जाणार नाहीत.','Display layout' => 'डिस्प्ले लेआउट','Choose how saved addresses are displayed at checkout and on the cart.' => 'चेकआउट करताना आणि कार्टमध्ये सेव्ह केलेले पत्ते कसे दिसतील ते निवडा.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'चेकआउट करताना आणि कार्टवर लागू होते. अकाउंट पेजवरील सेव्ह केलेले पत्ते नेहमी कार्ड्स लेआउट वापरतात.','Address cards' => 'पत्त्याचे कार्ड','Address list' => 'पत्त्यांची यादी','Dropdown field' => 'ड्रॉपडाउन फील्ड','Address search' => 'पत्ता शोध','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'जेव्हा ग्राहकाकडे किमान इतके पत्ते जतन केलेले असतील, तेव्हा फ्रंटएंडवर पत्ता शोध फिल्टर दाखवा.','Not used when display layout is set to dropdown field.' => 'जेव्हा डिस्प्ले लेआउट ड्रॉपडाउन फील्डवर सेट केलेला असतो, तेव्हा याचा वापर केला जात नाही.','Addresses' => 'पत्ते','Enable cart page optimizations to see more options' => 'अधिक पर्याय पाहण्यासाठी कार्ट पेज ऑप्टिमायझेशन सक्षम करा.','Sticky order summary' => 'चिकट ऑर्डर सारांश','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'कार्ट पेजवर कूपन कोड विभाग कोठे दाखवायचा याची जागा निवडा. हे फक्त तेव्हाच लागू होते जेव्हा AJAX कार्ट सक्षम केलेले असेल आणि WooCommerce सेटिंग्जमध्ये कूपन कोडचा वापर सक्षम केलेला असेल.','Layout of cross-sell' => 'क्रॉस-सेलची मांडणी','Cross-sells displayed' => 'क्रॉस-सेल्स प्रदर्शित केले','Items' => 'वस्तू','Cart page optimization' => 'कार्ट पेज ऑप्टिमायझेशन','Give your cart the same clear, conversion-focused layout as your checkout.' => 'तुमच्या कार्टला तुमच्या चेकआउटप्रमाणेच स्पष्ट, रूपांतरणावर लक्ष केंद्रित करणारा लेआउट द्या.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'खरेदीचा अनुभव सुसंगत ठेवण्यासाठी, कार्टची मांडणी चेकआउट पेजशी जुळवा.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'बॅकग्राउंडमध्ये कार्ट नेहमी अद्ययावत ठेवा, वस्तूंची संख्या बदलल्यावर संपूर्ण पेज पुन्हा लोड होणार नाही.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'कूपन कोड, शिपिंग आणि क्रॉस-सेल्स नेमके तिथेच ठेवा जिथे त्यांचे सर्वाधिक रूपांतर होते.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'स्क्रोल करताना ऑर्डरचा सारांश दिसेल असा ठेवा आणि जिथे खरेदीदारांना खात्रीची गरज आहे तिथे विश्वासाची चिन्हे जोडा.','Columns' => 'स्तंभ','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'चेकआउटच्या पायऱ्या, ऑर्डरचा सारांश आणि इतर विभागांसाठी सर्वसाधारण शैली. इतर चेकआउट, कार्ट, धन्यवाद (ऑर्डर मिळाली), आणि ऑर्डर पहा या पृष्ठांना लागू होते.','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => '<em>&quot;स्प्लिट&quot;</em> डिझाइन टेम्पलेटसह <em>&quot;१ कॉलम&quot;</em> लेआउट वापरताना, पेज साइडबार विजेट एरिया (चेकआउट साइडबार, कार्ट साइडबार किंवा ऑर्डर रिसीव्हड साइडबार) सक्रिय असेल तरच उजवा कॉलम दाखवला जातो. अन्यथा, पेज स्प्लिट स्टाईलसह एकाच कॉलममध्ये राहते.','Split column background' => 'स्प्लिट कॉलम पार्श्वभूमी','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'स्प्लिट डिझाइनच्या दुय्यम कॉलमसाठी पार्श्वभूमीचा रंग निवडा. ऑर्डर सारांशाचा पार्श्वभूमी रंग वापरण्यासाठी हे रिकामे सोडा.','Page templates' => 'पृष्ठ टेम्पलेट्स','Checkout template' => 'चेकआउट टेम्पलेट','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'चेकआउट करताना कमी व्यत्यय येण्यासाठी शिफारस केली आहे. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">कार्ट सोडून देण्याबद्दलचे संशोधन वाचा</a> .','Sticky progress bar' => 'चिकट प्रगती बार','Progress bar style' => 'प्रोग्रेस बार शैली','Order totals' => 'ऑर्डरची एकूण रक्कम','Background color' => 'पार्श्वभूमीचा रंग','Action link' => 'कृती लिंक','Mobile order summary' => 'मोबाइल ऑर्डर सारांश','Mobile initial state' => 'मोबाईलची प्रारंभिक स्थिती','Enable editing cart items at checkout' => 'चेकआउट करताना कार्टमधील वस्तू संपादित करण्याची परवानगी द्या','Allow customers to change product quantities or remove items directly at the checkout page.' => 'ग्राहकांना थेट चेकआउट पेजवर उत्पादनांची संख्या बदलण्याची किंवा वस्तू काढून टाकण्याची परवानगी द्या.','Cart item errors' => 'कार्टमधील वस्तूंच्या त्रुटी','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'हे फक्त तेव्हाच लागू होते जेव्हा कूपन कोड चेकआउट किंवा कार्ट पेजवर स्वतंत्र विभाग म्हणून दाखवला जातो आणि WooCommerce सेटिंग्जमध्ये कूपन कोडचा वापर सक्षम केलेला असतो.','Coupon codes position' => 'कूपन कोडची स्थिती','Apply coupon button' => 'कूपन लागू करा बटण','Select style of the "apply coupon" button.' => '&#39;कूपन लागू करा&#39; बटणाची शैली निवडा.','Address line 2' => 'पत्ता ओळ २','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'ही सेटिंग चेकआउट आणि लोकल पिकअप या दोन्ही विभागांमध्ये सामायिक आहे. लोकल पिकअप विभागात, शिप/पिकअप निवडक शिपिंग पद्धत विभागात (पत्त्याच्या आधी) दिसेल की एक स्वतंत्र विभाग म्हणून (नंतर) दिसेल, हे देखील ती ठरवते.','Customer accounts' => 'ग्राहक खाती','Guest checkout' => 'अतिथी चेकआउट','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'वू कॉमर्स अकाउंट्स सेटिंग्ज पेजवरील गेस्ट चेकआउट, लॉगिन आणि अकाउंट तयार करण्याचे पर्याय. तुमच्या सोयीसाठी ते येथे व्यवस्थापित केले जातात, जेणेकरून तुम्ही प्रत्येक सेटिंग्ज प्रोफाइलसाठी वेगवेगळी मूल्ये वापरू शकता.','Allow customers to checkout without an account' => 'ग्राहकांना खात्याशिवाय खरेदी पूर्ण करण्याची परवानगी द्या','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => 'अशी <strong>शिफारस केली जाते</strong> जेणेकरून ग्राहकांना चेकआउट दरम्यान खाते तयार करण्यास किंवा लॉग इन करण्यास सांगितले जाणार नाही, ज्यामुळे रूपांतरण दर कमी होऊ शकतो.','When disabled, customers must log in or create an account to complete the purchase.' => 'जेव्हा हे अक्षम केलेले असते, तेव्हा खरेदी पूर्ण करण्यासाठी ग्राहकांना लॉग इन करावे लागेल किंवा खाते तयार करावे लागेल.','Login at checkout' => 'चेकआउट करताना लॉग इन करा','Enable log-in during checkout' => 'चेकआउट करताना लॉग-इन सक्षम करा','Show a link for returning customers to log in from the checkout page.' => 'परत येणाऱ्या ग्राहकांना चेकआउट पेजवरून लॉग इन करण्यासाठी एक लिंक दाखवा.','Account creation' => 'खाते तयार करणे','Allow customers to create an account during checkout' => 'ग्राहकांना चेकआउट दरम्यान खाते तयार करण्याची परवानगी द्या','Customers can create an account before placing their order.' => 'ग्राहक ऑर्डर देण्यापूर्वी खाते तयार करू शकतात.','Allow customers to create an account from the My account page' => 'ग्राहकांना &#39;माझे खाते&#39; पृष्ठावरून खाते तयार करण्याची परवानगी द्या.','Customers can register a new account from the My account page.' => 'ग्राहक &#39;माझे खाते&#39; पृष्ठावरून नवीन खात्याची नोंदणी करू शकतात.','Username' => 'वापरकर्तानाव','Generate from customer\'s name' => 'ग्राहकाच्या नावावरून तयार करा','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => 'अशी <strong>शिफारस केली जाते</strong> जेणेकरून ग्राहकांना चेकआउट करताना युझरनेम निवडायला सांगितले जाणार नाही, ज्यामुळे रूपांतरण दर कमी होऊ शकतो.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'ग्राहकाच्या नावावरून, किंवा नाव वापरता येत नसल्यास ईमेल पत्त्यावरून वापरकर्तानाव तयार केले जाते.','Password' => 'पासवर्ड','Send password setup link' => 'पासवर्ड सेटअप लिंक पाठवा','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => 'अशी <strong>शिफारस केली जाते</strong> जेणेकरून ग्राहकांना चेकआउट करताना पासवर्ड सेट करण्यास सांगितले जाणार नाही, ज्यामुळे रूपांतरण दर कमी होऊ शकतो.','Customers receive an email to create their password securely.' => 'ग्राहकांना त्यांचा पासवर्ड सुरक्षितपणे तयार करण्यासाठी एक ईमेल प्राप्त होतो.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'नोंदणीकृत ग्राहकांना लॉग इन न करता चेकआउट पूर्ण करू द्या आणि संपर्क तपशील जुळल्यास ऑर्डर त्यांच्या विद्यमान खात्याशी जोडा.','Existing account message' => 'विद्यमान खाते संदेश','Let customers create an account after placing their order, from the thank you page.' => 'ग्राहकांना त्यांची ऑर्डर दिल्यानंतर, थँक्यू पेजवरून खाते तयार करू द्या.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'जेव्हा गेस्ट चेकआउट आणि अकाउंट मॅचिंग सक्षम केलेले असते, तेव्हा या विभागातील पर्याय उपलब्ध असतात. विलंबित अकाउंट निर्मिती कॉन्फिगर करण्यासाठी वरील दोन्ही वैशिष्ट्ये सक्षम करा.','Enable delayed account creation' => 'विलंबित खाते निर्मिती सक्षम करा','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'जेव्हा गेस्ट चेकआउट आणि अकाउंट मॅचिंग दोन्ही सक्षम केलेले असतील, तेव्हा विलंबित खाते निर्मिती सक्षम करा.','Section position' => 'विभागाची स्थिती','Before customer details section' => 'ग्राहक तपशील विभागापूर्वी','After customer details section' => 'ग्राहक तपशील विभागानंतर','Account creation benefits' => 'खाते तयार करण्याचे फायदे','Leaving the field empty will display the default text.' => 'हे क्षेत्र रिकामे सोडल्यास डीफॉल्ट मजकूर दिसेल.','Inline buttons' => 'इनलाइन बटणे','Required fields' => 'आवश्यक फील्ड्स','Enable gift message fields at checkout' => 'चेकआउट करताना भेट संदेशासाठी फील्ड्स सक्षम करा','Expanded gift message' => 'विस्तृत भेट संदेश','Display gift message field always expanded' => 'भेट संदेशाचे क्षेत्र नेहमी विस्तारित स्वरूपात दाखवा','Gift message in order details' => 'ऑर्डरच्या तपशिलात भेटवस्तू संदेश','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'सध्या या विभागात कोणतेही इंटिग्रेशन उपलब्ध नाही. प्रत्येक प्लगइन आणि थीमशी संबंधित पर्याय, ते प्लगइन किंवा थीम सक्रिय केल्यावरच येथे दिसतील.','Phone fields' => 'फोन फील्ड्स','Field visibility' => 'क्षेत्रीय दृश्यमानता','Field position' => 'क्षेत्रीय स्थिती','Phone country code & validation' => 'फोन देश कोड आणि प्रमाणीकरण','Country' => 'देश','Enable country on phone fields' => 'फोन फील्डवर देश सक्षम करा','Filter countries for shipping or billing' => 'शिपिंग किंवा बिलिंगसाठी देश फिल्टर करा','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'प्रत्येक फोन फील्डवरील देश निवडक तुमच्या स्टोअरवर शिपिंग किंवा बिलिंगसाठी परवानगी असलेल्या देशांपुरता मर्यादित करा.','Validation' => 'प्रमाणीकरण','Enable simple validation based on country rules' => 'देशाच्या नियमांवर आधारित साधे प्रमाणीकरण सक्षम करा','Checks that the phone number is valid for the selected country, including country code and length.' => 'निवडलेल्या देशासाठी फोन नंबर वैध आहे की नाही, तसेच देशाचा कोड आणि कालावधी तपासला जातो.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'निवडलेल्या देशासाठी नंबर वैध मोबाईल, फिक्स्ड लाइन किंवा इतर स्वीकृत प्रकारचा असल्याची अधिक कठोर तपासणी केली जाते. काही वैध नंबर नाकारले जाऊ शकतात.','Validation types' => 'प्रमाणीकरण प्रकार','Placeholders' => 'प्लेसहोल्डर्स','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'सध्या व्यवस्थापित करण्यासाठी कोणतेही लायसन्स की नाहीत. जेव्हा एखादे परवानाधारक फ्लूइड चेकआउट प्लगइन किंवा अॅड-ऑन सक्रिय असेल, तेव्हा लायसन्स की येथे दिसतील.','Default delivery type' => 'डीफॉल्ट वितरण प्रकार','Choose which delivery type will be selected by default.' => 'डीफॉल्टनुसार कोणता वितरण प्रकार निवडला जाईल ते निवडा.','Shipping zone fields' => 'शिपिंग झोन फील्ड्स','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'लोकल पिकअप शिपिंग झोन फिल्टर फील्डसाठी कोणती फील्ड्स दाखवली जातील ते निवडा. सर्व उपलब्ध पर्याय पाहण्यासाठी हे रिकामे सोडा.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'स्थानिक पिकअप शिपिंग पद्धतींसाठी ही फील्ड्स फिल्टर म्हणून दाखवली जातील. सुसंगत प्लगइन्सना योग्यरित्या काम करण्यासाठी काही फील्ड्सची आवश्यकता असल्यास, येथे निवडलेली नसतानाही ती चेकआउटच्या वेळी दिसू शकतात.','Order shipping address' => 'ऑर्डर पाठवण्याचा पत्ता','Order pay page optimization' => 'ऑर्डर पे पेज ऑप्टिमायझेशन','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'न भरलेल्या ऑर्डर्सना चेकआउटप्रमाणेच स्पष्ट, रूपांतरणावर लक्ष केंद्रित करणारा लेआउट द्या.','Optimize the layout of the order pay page for orders pending payment.' => 'ज्या ऑर्डर्सचे पेमेंट प्रलंबित आहे, त्यांच्यासाठी ऑर्डर पे पेजचा लेआउट ऑप्टिमाइझ करा.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'खरेदीचा अनुभव सुसंगत ठेवण्यासाठी, ऑर्डर आणि पेमेंटची प्रक्रिया तुमच्या चेकआउट प्रक्रियेशी जुळवा.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'जिथे ग्राहकांना पैसे देण्यापूर्वी खात्रीची गरज असते, तिथे विश्वासाची चिन्हे आणि बॅजेस लावा.','Thank you page optimization' => 'पेज ऑप्टिमायझेशनबद्दल धन्यवाद','Make the thank you page and order details clearer for customers after they buy.' => 'ग्राहकांनी खरेदी केल्यानंतर त्यांच्यासाठी आभार पृष्ठ आणि ऑर्डरचा तपशील अधिक स्पष्ट बनवा.','Optimize the thank you page and account order details with a clearer layout.' => 'अधिक सुस्पष्ट मांडणी वापरून आभार पृष्ठ आणि खाते ऑर्डर तपशील अनुकूलित करा.','Show order status progress, actions, downloads, and notes where they make sense.' => 'जिथे योग्य वाटेल तिथे ऑर्डरच्या स्थितीची प्रगती, केलेल्या कृती, डाउनलोड्स आणि नोंदी दाखवा.','Customize order details sections on email notifications.' => 'ईमेल सूचनांवरील ऑर्डर तपशील विभाग सानुकूलित करा.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'खरेदीनंतर ग्राहकांना जिथे खात्रीची गरज असते, तिथे विश्वासाची चिन्हे आणि बॅजेस लावा.','Email notifications' => 'ईमेल सूचना','Enable thank you page and order details optimizations to see more options' => 'अधिक पर्याय पाहण्यासाठी धन्यवाद पृष्ठ आणि ऑर्डर तपशील ऑप्टिमायझेशन सक्षम करा.','Use wide layout on thank you page' => 'धन्यवाद पृष्ठावर विस्तृत मांडणीचा वापर करा','These options affect the thank you page, view order details on account pages and on email notifications.' => 'हे पर्याय थँक्यू पेज, अकाउंट पेजवरील ऑर्डर डिटेल्स पाहणे आणि ईमेल नोटिफिकेशन्स यांवर परिणाम करतात.','Save settings' => 'सेटिंग्ज जतन करा','Docs' => 'डॉक्स','Cart' => 'कार्ट','Thank you' => 'धन्यवाद','Address autocomplete' => 'पत्ता ऑटो-कंप्लीट','Trust badges' => 'विश्वास बॅजेस','You do not have permission to save these settings.' => 'तुम्हाला या सेटिंग्ज जतन करण्याची परवानगी नाही.','Invalid save request.' => 'अवैध सेव्ह विनंती.','Your settings have been saved.' => 'तुमची सेटिंग्ज जतन करण्यात आली आहेत.','Saving...' => 'जतन करत आहे...','Settings could not be saved. Please try again.' => 'सेटिंग्ज जतन करता आल्या नाहीत. कृपया पुन्हा प्रयत्न करा.','Dismiss notice' => 'नोटीस रद्द करा','Open settings menu' => 'सेटिंग्ज मेनू उघडा','Close settings menu' => 'सेटिंग्ज मेनू बंद करा','Preview' => 'पूर्वावलोकन','Expand preview' => 'पूर्वावलोकन विस्तृत करा','Collapse preview' => 'पूर्वावलोकन संकुचित करा','Show header and footer' => 'शीर्षलेख आणि तळटीप दाखवा','Hide header and footer' => 'हेडर आणि फुटर लपवा','Page preview' => 'पृष्ठ पूर्वावलोकन','Preview viewport' => 'पूर्वावलोकन व्ह्यूपोर्ट','Tablet' => 'टॅब्लेट','Desktop' => 'डेस्कटॉप','Preview width' => 'पूर्वावलोकन रुंदी','Decrease width' => 'रुंदी कमी करा','Preview width in pixels' => 'पिक्सेलमध्ये पूर्वावलोकन रुंदी','Increase width' => 'रुंदी वाढवा','Preview as' => 'पूर्वावलोकन म्हणून','Guest' => 'पाहुणे','Logged in' => 'लॉग इन केले','Preview page' => 'पूर्वावलोकन पृष्ठ','Expand preview for a closer look' => 'अधिक जवळून पाहण्यासाठी पूर्वावलोकन विस्तृत करा','Available with %s.' => '%s सह उपलब्ध.','Turn them on' => 'त्यांना चालू करा','Optimizations for this page are turned off. %s to preview the page.' => 'या पृष्ठासाठीचे अनुकूलन बंद केले आहे. पृष्ठाचे पूर्वावलोकन करण्यासाठी %s दाबा.','%s preview' => '%s पूर्वावलोकन','Isolated session · nothing is saved' => 'विलग सत्र · काहीही जतन केले जात नाही','Usage tracking' => 'वापराचा मागोवा घेणे','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'Fluid Checkout ला सुसंगतता सुधारण्यास मदत करण्यासाठी असंवेदनशील साइट पर्यावरण अहवाल पाठवा. खालील पर्यायांमध्ये सक्षम केल्याशिवाय अहवाल पाठवले जात नाहीत.','Send usage tracking reports to Fluid Checkout' => 'वापर ट्रॅकिंग अहवाल फ्लूइड चेकआउटला पाठवा','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'हे अहवाल आम्हाला तुमच्या साइटसाठी सुसंगतता आणि समर्थन सुधारण्यास मदत करतात आणि सक्षम केल्यावर साप्ताहिक पाठवले जातात.','No customer, admin user, or any other sensitive data is included in the reports.' => 'अहवालांमध्ये ग्राहक, प्रशासक वापरकर्ता किंवा इतर कोणतीही संवेदनशील माहिती समाविष्ट केलेली नाही.','Basic environment info' => 'मूलभूत पर्यावरण माहिती','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'वर्डप्रेस, पीएचपी, वूकॉमर्स, थीम आणि प्लगइनची सूची माहिती. रिपोर्टिंग सक्षम केले असल्यास ही माहिती नेहमी समाविष्ट असते. तुमची साइट कोणत्या वातावरणात कार्यरत आहे हे समजून घेण्यास आम्हाला मदत करते.','Plugin settings' => 'प्लगइन सेटिंग्ज','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'सपोर्ट विनंत्यांमध्ये मदत करण्यासाठी आणि तुम्ही आमचे प्लगइन कसे वापरत आहात हे समजून घेण्यास आम्हाला मदत करण्यासाठी फ्लूइड चेकआउट प्लगइन सेटिंग्ज पाठवते.','Coming soon' => 'लवकरच येत आहे','Sales metrics' => 'विक्री मेट्रिक्स','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'फ्लूइड चेकआउट इंस्टॉल करण्यापूर्वीच्या एका वर्षापासून ते आजपर्यंतची मासिक ऑर्डर संख्या आणि एकूण विक्री. आमचे प्लगइन्स इंस्टॉल केल्यामुळे तुम्ही अधिक पैसे कमवत आहात की नाही हे समजण्यास आम्हाला मदत होते. कोणताही ग्राहक किंवा वापरकर्ता डेटा कधीही पाठवला जात नाही.','Utilities' => 'उपयुक्तता','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => '<code>select2</code> ऐवजी <code>TomSelect</code> ड्रॉपडाउन घटक वापरा','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'TomSelect हा एक सोपा ड्रॉपडाउन सिलेक्शन कंपोनंट आहे, जो Select2 पेक्षा कमी चुका होण्याची शक्यता असलेला असून, तीच कार्यक्षमता देतो.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'या प्लगइनद्वारे ऑप्टिमाइझ केलेल्या पृष्ठांवरील फॉर्म फील्डमधील फॉन्टचा आकार 16px वर सेट करतो, जेणेकरून लहान उपकरणांवर फॉर्म फील्ड वापरताना ते आपोआप झूम इन होणार नाही.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'जेव्हा फॉन्टचा आकार 16px पेक्षा लहान असतो, तेव्हा मजकूर वाचायला सोपा करण्यासाठी सफारी आणि इतर ब्राउझर मोबाईल डिव्हाइसवर आपोआप झूम इन करू शकतात.','Enable script processing tracking on the browser console.' => 'ब्राउझर कन्सोलवर स्क्रिप्ट प्रोसेसिंग ट्रॅकिंग सक्षम करा.','Unminified assets' => 'अविभाजित मालमत्ता','Google Maps scripts' => 'गुगल मॅप्स स्क्रिप्ट्स','Do not remove duplicate Google Maps scripts' => 'डुप्लिकेट गूगल मॅप्स स्क्रिप्ट्स काढू नका','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'सक्षम केल्यावर, डुप्लिकेट गूगल मॅप्स स्क्रिप्ट्स काढल्या जाणार नाहीत, ज्यामुळे त्रुटी आणि कार्यक्षमतेच्या समस्या निर्माण होऊ शकतात. हा पर्याय फक्त समस्यानिवारण करतानाच वापरा.','Widget areas' => 'विजेट क्षेत्रे','Last step on mobile' => 'मोबाईलवरील शेवटची पायरी','Display widgets only at last step on mobile' => 'मोबाईलवर विजेट्स फक्त शेवटच्या टप्प्यावर दाखवा','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'मोबाइल डिव्हाइसवर शेवटची चेकआउट पायरी पाहतानाच चेकआउट ट्रस्ट बॅज विजेट्स दाखवा.','Standard' => 'मानक','VAT number field' => 'व्हॅट क्रमांक फील्ड','Add a VAT number field to the billing form.' => 'बिलिंग फॉर्ममध्ये व्हॅट क्रमांकासाठी जागा जोडा.','Field label' => 'फील्ड लेबल','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'व्हॅट नंबर फील्डचे लेबल (म्हणजेच, व्हॅट नंबर) सेट करा. बहुभाषिक वेबसाइटवर, हे फील्ड रिकामे सोडणे आणि मूळ स्ट्रिंगचे भाषांतर करणे अधिक चांगले आहे.','VAT Number' => 'व्हॅट क्रमांक','EU-VAT' => 'युरोपियन युनियन-व्हॅट','Enable the VAT number field to see more options' => 'अधिक पर्याय पाहण्यासाठी व्हॅट क्रमांक फील्ड सक्षम करा.','VAT validation' => 'व्हॅट पडताळणी','Validate VAT number field for EU-VAT during checkout' => 'चेकआउट करताना EU-VAT साठी VAT क्रमांक फील्ड प्रमाणित करा.','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'दिलेला व्हॅट क्रमांक युरोपियन VIES डेटाबेस (व्हॅट माहिती विनिमय प्रणाली) वर नोंदणीकृत असलेला वैध व्हॅट क्रमांक आहे की नाही हे तपासते.','Shop VAT number' => 'दुकान व्हॅट क्रमांक','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'ईयू-व्हॅट प्रमाणीकरणाची विनंती करण्यासाठी वापरलेला आणि पावत्यांवर छापलेला दुकानाचा व्हॅट क्रमांक.<br> <strong>आम्ही तुम्हाला तुमचा शॉप व्हॅट क्रमांक जोडण्याची जोरदार शिफारस करतो</strong> , अन्यथा VIES सल्लामसलतीचे निकाल लेखांकनाच्या दृष्टीने वैध ठरणार नाहीत.<br> उदा.: <code>ATU99999999</code> किंवा <code>EE999999999</code> .','Reverse charge' => 'उलट चार्ज','Apply reverse charge mechanism' => 'रिव्हर्स चार्ज यंत्रणा लागू करा','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'जेव्हा ग्राहकाचा व्हॅट क्रमांक वैध असेल, तेव्हा कराचा दर शून्य करा आणि पावत्यांवर &quot;रिव्हर्स चार्ज&quot; प्रदर्शित करा. दुकानाच्या देशानुसार वेगळ्या &quot;रिव्हर्स चार्ज&quot; मजकुराची आवश्यकता असू शकते.','Same country' => 'एकाच देशात','Apply reverse charge mechanism for transactions in the shop country:' => 'दुकानाच्या देशातील व्यवहारांसाठी रिव्हर्स चार्ज यंत्रणा लागू करा:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'दुकानाच्या देशातील कंपन्यांमधील व्यवहारांसाठी रिव्हर्स चार्ज यंत्रणा लागू करण्यास सक्षम करते.','Reverse charge exceptions' => 'रिव्हर्स चार्ज अपवाद','Select additional countries to skip applying the reverse charge mechanism.' => 'रिव्हर्स चार्ज यंत्रणा लागू न करण्यासाठी अतिरिक्त देश निवडा.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'वैध व्हॅट क्रमांक दिला असला तरीही, या देशांमधून येणाऱ्या ऑर्डरवर कर आकारला जाईल.','Reverse charge label on invoices' => 'पावत्यांवरील रिव्हर्स चार्ज लेबल','Set the label of "reverse charge" on the checkout page and order details.' => 'चेकआउट पेज आणि ऑर्डर डिटेल्सवर &quot;रिव्हर्स चार्ज&quot; चे लेबल सेट करा.','Reverse charge text on invoices' => 'पावत्यांवरील रिव्हर्स चार्ज मजकूर','Set the label of "reverse charge" text on invoices.' => 'इनव्हॉइसवर &quot;रिव्हर्स चार्ज&quot; मजकुराचे लेबल सेट करा.','Tax to be paid on reverse charge basis' => 'रिव्हर्स चार्ज तत्त्वावर कर भरावा लागेल','Company name' => 'कंपनीचे नाव','Autocomplete company name from VAT number' => 'व्हॅट नंबरवरून कंपनीचे नाव आपोआप पूर्ण करा','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'ग्राहकाने दिलेल्या वैध व्हॅट क्रमांकाच्या आधारे बिलिंग कंपनीचे नाव भरा.','Company name editing' => 'कंपनीचे नाव संपादन','Allow editing of auto-filled company name' => 'आपोआप भरलेल्या कंपनीच्या नावात बदल करण्याची परवानगी द्या.','When enabled, customers can change the company name associated with the provided VAT number.' => 'सक्षम केल्यावर, ग्राहक दिलेल्या व्हॅट क्रमांकाशी संबंधित कंपनीचे नाव बदलू शकतात.','EU-VAT for digital goods' => 'डिजिटल वस्तूंसाठी ईयू-व्हॅट','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => '१ जानेवारी २०१५ पासून, डिजिटल वस्तूंसंबंधीच्या EU व्हॅट नियमांमध्ये बदल करण्यात आले आहेत, ज्याचा परिणाम केवळ B2C व्यवहारांवर होतो. डिजिटल वस्तूंवरील व्हॅटची गणना ग्राहकाच्या स्थानाच्या आधारावर करणे आवश्यक आहे, आणि याचा पुरावा (IP पत्ता आणि बिलिंग पत्ता) गोळा करणे आवश्यक आहे.','Tax classes for digital goods' => 'डिजिटल वस्तूंसाठी कर वर्ग','Select some tax classes' => 'काही कर वर्ग निवडा','Location evidence' => 'स्थानाचा पुरावा','Collect customer\'s location evidence' => 'ग्राहकाच्या स्थानाचा पुरावा गोळा करा','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'आयपी ॲड्रेस जतन केला जातो आणि ग्राहकाच्या बिलिंग ॲड्रेसशी त्याची पडताळणी केली जाते. जर बिलिंग ॲड्रेस आणि आयपी ॲड्रेसमधील देश जुळत नसेल, तर ग्राहकांनी चेकआउट पेजवरील चेकबॉक्सवर खूण करून आपला बिलिंग ॲड्रेस निश्चित करणे आवश्यक आहे.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'हा पर्याय फ्लूइड चेकआउटमध्ये व्यवस्थापित केला जातो. <a href="%s">ग्राहक खाते सेटिंग्जमध्ये तो बदला</a> .','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'हा पर्याय फ्लूइड चेकआउटमध्ये व्यवस्थापित केला जातो. फ्लूइड चेकआउट &gt; ग्राहक खाती अंतर्गत तो बदला.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'हा पर्याय फ्लूइड चेकआउटमध्ये व्यवस्थापित केला जातो. जेव्हा फ्लूइड चेकआउट सक्रिय केले जाते, तेव्हा शिपिंगचे ठिकाण नेहमी &#39;डीफॉल्टनुसार ग्राहकाचा शिपिंग पत्ता&#39; असे सेट केलेले असते. तरीही, ग्राहक चेकआउट करताना वेगवेगळे शिपिंग आणि बिलिंग पत्ते देऊ शकतात.<br><br> <a href="%s">फ्लूइड चेकआउट सेटिंग्जमध्ये</a> डीफॉल्ट बिलिंग पत्ता शिपिंग पत्त्यासारखाच ठेवण्याचा पर्याय उपलब्ध आहे.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'हा पर्याय फ्लूइड चेकआउटमध्ये व्यवस्थापित केला जातो. जेव्हा फ्लूइड चेकआउट सक्रिय केले जाते, तेव्हा शिपिंगचे ठिकाण नेहमी &#39;डीफॉल्टनुसार ग्राहकाचा शिपिंग पत्ता&#39; असे सेट केलेले असते. तरीही, ग्राहक चेकआउट करताना वेगवेगळे शिपिंग आणि बिलिंग पत्ते देऊ शकतात.<br><br> डीफॉल्ट बिलिंग पत्ता आणि शिपिंग पत्ता एकच ठेवण्याचा पर्याय WooCommerce &gt; Settings &gt; Fluid Checkout येथे उपलब्ध आहे.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'ही सेटिंग्ज WP Admin &gt; Fluid Checkout &gt; Settings येथे हलवण्यात आली आहेत.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'हा WooCommerce सेटिंग्ज टॅब आता वापरला जात नाही आणि Fluid Checkout 6.0 मध्ये काढून टाकला जाईल.','Go to settings page' => 'सेटिंग्ज पेजवर जा','Hide this tab permanently' => 'हा टॅब कायमस्वरूपी लपवा','Site report preview' => 'साइट अहवाल पूर्वावलोकन','This is the data that would be included in the next site environment report based on your current settings.' => 'तुमच्या सध्याच्या सेटिंग्जच्या आधारावर, पुढील साइट पर्यावरण अहवालामध्ये या डेटाचा समावेश केला जाईल.','Loading report preview...' => 'अहवालाचे पूर्वावलोकन लोड होत आहे...','Could not load the site report preview. Try again.' => 'साइट रिपोर्टचा पूर्वावलोकन लोड होऊ शकला नाही. पुन्हा प्रयत्न करा.','Could not send the site report. Try again.' => 'साइटचा अहवाल पाठवता आला नाही. पुन्हा प्रयत्न करा.','Site report sent successfully.' => 'साइटचा अहवाल यशस्वीरित्या पाठवण्यात आला.','Enable and send now' => 'सक्षम करा आणि आता पाठवा','Close' => 'बंद करा','A site report request is already in progress. Try again in a moment.' => 'साइट रिपोर्टची विनंती आधीच विचाराधीन आहे. थोड्या वेळाने पुन्हा प्रयत्न करा.','Site environment reporting is disabled.' => 'साइट पर्यावरण अहवाल देणे अक्षम केले आहे.','No site report data is available to send.' => 'पाठवण्यासाठी कोणताही साइट रिपोर्ट डेटा उपलब्ध नाही.','This site domain cannot send environment reports (local or development domains are excluded).' => 'हे साइट डोमेन पर्यावरण अहवाल पाठवू शकत नाही (स्थानिक किंवा विकास डोमेन वगळण्यात आले आहेत).','A site report was sent recently. Try again later.' => 'नुकताच एक साइट अहवाल पाठवण्यात आला आहे. कृपया नंतर पुन्हा प्रयत्न करा.','The site report could not be sent. Try again later.' => 'साइटचा अहवाल पाठवता आला नाही. कृपया नंतर पुन्हा प्रयत्न करा.','Site environment reporting is not available.' => 'साइट पर्यावरण अहवाल उपलब्ध नाही.','No site report data is available for the selected settings.' => 'निवडलेल्या सेटिंग्जसाठी कोणताही साइट रिपोर्ट डेटा उपलब्ध नाही.','You are not allowed to manage site reports.' => 'तुम्हाला साइट अहवाल व्यवस्थापित करण्याची परवानगी नाही.','PRO feature' => 'प्रो वैशिष्ट्य','Other plugins' => 'इतर प्लगइन','Get only this add-on &mdash; %s' => 'फक्त हे ॲड-ऑन मिळवा — %s','Install add-on' => 'अ‍ॅड-ऑन स्थापित करा','Upgrade to PRO &mdash; %s' => 'प्रो मध्ये अपग्रेड करा — %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => 'हे पर्याय अनलॉक करण्यासाठी <a target="_blank" href="%1$s">%2$ मिळवा</a> .','Add-on' => 'अ‍ॅड-ऑन','View documentation' => 'दस्तऐवज पहा','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'विनंत्यांसाठी लॉग-इन केलेला वर्डप्रेस वापरकर्ता आवश्यक आहे. सध्याच्या वापरकर्त्याचा डेटा वापरण्यासाठी user_id वगळा, किंवा जेव्हा कॉलर त्या वापरकर्त्याला संपादित करू शकतो (edit_user क्षमता), तेव्हा दुसऱ्या खात्याला लक्ष्य करण्यासाठी user_id पास करा. अप्रमाणित विनंत्या fc_api_forbidden परत करतात. अवैध user_id fc_api_user_not_found परत करतो.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'जेव्हा हँडलर पेलोड परत करतो तेव्हा { &quot;data&quot;: { ... } } सह HTTP 200.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'जेव्हा कोणताही पेलोड (उदाहरणार्थ DELETE) नसतो तेव्हा { &quot;success&quot;: true } सह HTTP 200.','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'अपयश आल्यास WP_Error (कोड, संदेश, डेटा.स्टेटस) मधून वर्डप्रेस REST त्रुटी JSON परत मिळतो. वायर कोडमध्ये fc_api_* हा उपसर्ग वापरला जातो.','Forbidden access.' => 'प्रवेशास मनाई आहे.','Target user was not found.' => 'लक्ष्यित वापरकर्ता आढळला नाही.','This feature is not available.' => 'हे वैशिष्ट्य उपलब्ध नाही.','A required address field is missing.' => 'पत्त्यासाठी आवश्यक असलेले एक फील्ड उपलब्ध नाही.','Postcode or ZIP is invalid.' => 'पोस्टल कोड किंवा झिप चुकीचा आहे.','Phone number is invalid.' => 'फोन नंबर चुकीचा आहे.','State or county is invalid.' => 'राज्य किंवा जिल्हा अमान्य आहे.','Country is invalid or has no address fields.' => 'देश अवैध आहे किंवा त्यात पत्त्यासाठी जागा नाही.','The request could not be processed.' => 'विनंतीवर प्रक्रिया करता आली नाही.','Back to previous step' => 'मागील पायरीवर परत जा','Skip to settings' => 'सेटिंग्जवर जा','Start over and return to the first guided setup step' => 'पुन्हा सुरू करा आणि पहिल्या मार्गदर्शित सेटअप पायरीवर परत जा.','Start over' => 'पुन्हा सुरू करा','Please complete all sub-steps before continuing.' => 'कृपया पुढे जाण्यापूर्वी सर्व उप-टप्पे पूर्ण करा.','Expand' => 'विस्तार करा','Collapse' => 'संकुचित करा','Skip' => 'वगळा','Mark as complete' => 'पूर्ण झाले म्हणून चिन्हांकित करा','Mark as incomplete' => 'अपूर्ण म्हणून चिन्हांकित करा','View full-size image: %s' => 'पूर्ण-आकाराची प्रतिमा पहा: %s','Full-size setup guide image' => 'पूर्ण-आकाराचे सेटअप मार्गदर्शक चित्र','Close image' => 'प्रतिमा बंद करा','Fluid Checkout Guided Setup' => 'फ्लुइड चेकआउट गाइडेड सेटअप','Welcome' => 'स्वागत आहे','Explore your checkout' => 'तुमच्या चेकआउटची तपासणी करा','All set' => 'सर्व तयार आहे','You do not have permission to access this page.' => 'तुम्हाला या पृष्ठावर प्रवेश करण्याची परवानगी नाही.','Go to step %1$d: %2$s' => 'पायरी %1$d: %2$s वर जा','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'ही मार्गदर्शित सेटअप प्रक्रिया तुम्हाला फ्लूइड चेकआउटशी परिचित होण्यास मदत करते. खाली दिलेले टप्पे सध्या तात्पुरते आहेत.','Continue to the next step when you are ready.' => 'तुम्ही तयार असाल तेव्हा पुढील पायरीवर जा.','Open your store checkout to see Fluid Checkout in action.' => 'फ्लुइड चेकआउट प्रत्यक्ष कसे काम करते हे पाहण्यासाठी तुमच्या स्टोअरचे चेकआउट उघडा.','View checkout page' => 'चेकआउट पेज पहा','You can return to Fluid Checkout settings to continue configuring your store.' => 'तुमच्या स्टोअरचे कॉन्फिगरेशन सुरू ठेवण्यासाठी तुम्ही फ्लुइड चेकआउट सेटिंग्जवर परत जाऊ शकता.','Review checkout and cart settings' => 'चेकआउट आणि कार्ट सेटिंग्जचे पुनरावलोकन करा','Explore add-ons from the dashboard' => 'डॅशबोर्डवरून अॅड-ऑन्स एक्सप्लोर करा','Finish & go to settings' => 'पूर्ण करा आणि सेटिंग्जमध्ये जा.','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'बिलिंग फोन फील्ड व्हिजिबिलिटी ऑप्शनला जुन्या व्हॅल्यूवरून अपडेट करून WooCommerce च्या नियमांनुसार जुळवा.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'शिपिंग फोन फील्ड व्हिजिबिलिटी ऑप्शनला जुन्या व्हॅल्यूवरून अपडेट करून WooCommerce च्या नियमांनुसार जुळवा.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'ऑर्डर सारांशाच्या पार्श्वभूमी रंगाची सेटिंग नवीन स्प्लिट डिझाइनच्या दुय्यम स्तंभाच्या पार्श्वभूमी रंगाच्या पर्यायामध्ये कॉपी करा.','The enhanced select fields feature is always disabled when using the 